-- Sideline database schema — GENERATED by `npm run db:bundle`; do not edit.
-- Source: supabase/migrations/ (42 files).
--
-- Paste the whole file into the SQL Editor of a NEW, empty Supabase
-- project and run it once. Then (optionally, dev/staging only) run
-- supabase/seed/demo_seed.sql. See docs/database.md.

-- ===========================================================================
-- 20261101100000_extensions_and_helpers.sql
-- ===========================================================================

-- Purpose: extensions and small helpers every later migration reuses.
--
-- btree_gist lets bookings use a GiST EXCLUDE constraint that combines an
-- equality column (court_id) with a time-range overlap (&&): double
-- booking is then impossible at the database level, even under
-- concurrent requests (same mechanism as match-pickleball).
create extension if not exists btree_gist;

-- Keeps an `updated_at` column current on every UPDATE.
create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

comment on function public.set_updated_at() is
  'Generic BEFORE UPDATE trigger: sets updated_at = now().';

-- Last 10 digits of a phone number, so "+63 917 555 0142" and
-- "0917 555 0142" compare equal.
create or replace function public.phone_key(p_phone text)
returns text
language sql
immutable
set search_path = ''
as $$
  select right(regexp_replace(coalesce(p_phone, ''), '\D', '', 'g'), 10);
$$;

-- Today and the current hour in a tenant's timezone (business dates are
-- local calendar dates, not UTC ones).
create or replace function public.local_today(p_timezone text default 'Asia/Manila')
returns date
language sql
stable
set search_path = ''
as $$
  select (now() at time zone p_timezone)::date;
$$;

-- ===========================================================================
-- 20261101100100_platform_and_tenants.sql
-- ===========================================================================

-- Purpose: who runs the platform, the plans businesses subscribe to, the
-- businesses themselves (tenants), their booking rules and their staff,
-- plus the role helpers every RLS policy is built on.
--
-- Multi-tenancy model: every business-owned row carries tenant_id. RLS
-- lets a signed-in user see a tenant's private data only when they are an
-- active staff member of that tenant (or a platform admin), and each
-- staff role maps to a fixed set of permissions (role_permissions below,
-- mirrored by src/utils/permissions.ts).

-- ---------------------------------------------------------------------------
-- Platform admins (Sideline's own team)
-- ---------------------------------------------------------------------------
create table public.platform_admins (
  user_id uuid primary key references auth.users (id) on delete cascade,
  created_at timestamptz not null default now()
);

comment on table public.platform_admins is
  'Sideline staff with access to every tenant. Rows are added by hand in '
  'the SQL Editor (see docs/database.md), never from the app.';

create or replace function public.is_platform_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.platform_admins where user_id = (select auth.uid())
  );
$$;

-- ---------------------------------------------------------------------------
-- Plans (product configuration, so they live in the migration)
-- ---------------------------------------------------------------------------
create table public.plans (
  id text primary key check (id ~ '^[a-z][a-z0-9_]*$'),
  name text not null check (char_length(name) between 1 and 50),
  description text not null default '',
  monthly_price_centavos integer not null check (monthly_price_centavos >= 0),
  annual_price_centavos integer not null check (annual_price_centavos >= 0),
  -- NULL = unlimited.
  limit_locations integer check (limit_locations >= 0),
  limit_courts integer check (limit_courts >= 0),
  limit_staff integer check (limit_staff >= 0),
  limit_bookings_per_month integer check (limit_bookings_per_month >= 0),
  features text[] not null default '{}',
  highlighted boolean not null default false,
  is_public boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger set_plans_updated_at
  before update on public.plans
  for each row execute function public.set_updated_at();

insert into public.plans (
  id, name, description, monthly_price_centavos, annual_price_centavos,
  limit_locations, limit_courts, limit_staff, limit_bookings_per_month,
  features, highlighted, is_public, sort_order
) values
  ('starter', 'Starter', 'For a single venue getting online bookings off the ground.',
    149000, 1490000, 1, 4, 3, 400,
    array['Online booking page', 'Court calendar', 'GCash & cash payments', 'Customer list', 'Email confirmations'],
    false, true, 1),
  ('growth', 'Growth', 'For growing clubs adding courts, staff and a second site.',
    399000, 3990000, 3, 12, 10, 2000,
    array['Everything in Starter', 'Up to 3 locations', 'Custom branding', 'Peak & off-peak pricing', 'Staff roles', 'Revenue reports'],
    true, true, 2),
  ('pro', 'Pro', 'For multi-site operators who need deeper control.',
    799000, 7990000, 6, 30, 30, null,
    array['Everything in Growth', 'Unlimited bookings', 'Card payments', 'Advanced analytics', 'Priority support'],
    false, true, 3),
  ('enterprise', 'Enterprise', 'Custom limits, onboarding and SLAs for large networks.',
    1499000, 14990000, null, null, null, null,
    array['Everything in Pro', 'Unlimited locations & courts', 'Dedicated success manager', 'Custom domain', 'SLA & audit exports'],
    false, false, 4);

-- ---------------------------------------------------------------------------
-- Tenants (one row per pickleball business)
-- ---------------------------------------------------------------------------
create table public.tenants (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) <= 60),
  name text not null check (char_length(name) between 2 and 100),
  legal_name text not null default '' check (char_length(legal_name) <= 150),
  status text not null default 'trialing'
    check (status in ('active', 'trialing', 'past_due', 'suspended', 'cancelled')),
  owner_name text not null default '' check (char_length(owner_name) <= 100),
  owner_email text not null default '' check (char_length(owner_email) <= 254),
  phone text not null default '' check (char_length(phone) <= 30),
  city text not null default '' check (char_length(city) <= 100),
  timezone text not null default 'Asia/Manila',
  currency text not null default 'PHP' check (currency = 'PHP'),
  about text not null default '' check (char_length(about) <= 1000),
  brand_primary text not null default '#1f5641' check (brand_primary ~ '^#[0-9a-fA-F]{6}$'),
  brand_accent text not null default '#c9e86a' check (brand_accent ~ '^#[0-9a-fA-F]{6}$'),
  brand_monogram text not null default '' check (char_length(brand_monogram) <= 2),
  brand_tagline text not null default '' check (char_length(brand_tagline) <= 120),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public.tenants is
  'Pickleball businesses. Public-readable (it is their public profile); '
  'status changes only through set_tenant_status() / billing functions.';

create trigger set_tenants_updated_at
  before update on public.tenants
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Booking rules (1:1 with tenants)
-- ---------------------------------------------------------------------------
create table public.booking_rules (
  tenant_id uuid primary key references public.tenants (id) on delete cascade,
  min_duration_minutes integer not null default 60 check (min_duration_minutes between 30 and 720),
  max_duration_minutes integer not null default 180 check (max_duration_minutes between 30 and 720),
  advance_booking_days integer not null default 30 check (advance_booking_days between 1 and 365),
  cancellation_window_hours integer not null default 24 check (cancellation_window_hours between 0 and 336),
  hold_minutes integer not null default 15 check (hold_minutes between 5 and 1440),
  require_prepayment boolean not null default true,
  allow_walk_ins boolean not null default true,
  peak_start_hour smallint not null default 17 check (peak_start_hour between 0 and 23),
  peak_days text not null default 'all' check (peak_days in ('all', 'weekdays', 'weekends')),
  payment_methods text[] not null default array['gcash', 'maya', 'bank_transfer', 'cash']
    check (
      cardinality(payment_methods) > 0
      and payment_methods <@ array['gcash', 'maya', 'card', 'bank_transfer', 'cash']
    ),
  updated_at timestamptz not null default now(),
  constraint booking_rules_duration_order check (min_duration_minutes <= max_duration_minutes)
);

create trigger set_booking_rules_updated_at
  before update on public.booking_rules
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Staff (tenant members). user_id is filled in when the invited person
-- signs in with the same email (see link_staff_on_signup()).
-- ---------------------------------------------------------------------------
create table public.staff_members (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants (id) on delete cascade,
  user_id uuid references auth.users (id) on delete set null,
  name text not null check (char_length(name) between 1 and 100),
  email text not null check (email ~ '^\S+@\S+\.\S+$' and char_length(email) <= 254),
  phone text not null default '' check (char_length(phone) <= 30),
  role text not null check (role in ('owner', 'manager', 'front_desk', 'coach')),
  -- Locations this person works at; empty = all locations.
  location_ids uuid[] not null default '{}',
  status text not null default 'invited' check (status in ('active', 'invited', 'disabled')),
  last_active_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index staff_members_tenant_email_key on public.staff_members (tenant_id, lower(email));
create index staff_members_user_id_idx on public.staff_members (user_id);

create trigger set_staff_members_updated_at
  before update on public.staff_members
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Role helpers (SECURITY DEFINER so policies can call them without
-- recursing into staff_members' own RLS).
-- ---------------------------------------------------------------------------
create or replace function public.staff_role(p_tenant uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select role
  from public.staff_members
  where tenant_id = p_tenant
    and user_id = (select auth.uid())
    and status = 'active'
  limit 1;
$$;

-- Mirrors rolePermissions in src/utils/permissions.ts.
create or replace function public.role_permissions(p_role text)
returns text[]
language sql
immutable
set search_path = ''
as $$
  select case p_role
    when 'owner' then array['dashboard', 'calendar', 'bookings', 'customers', 'payments',
                            'venues', 'staff', 'reports', 'settings', 'billing']
    when 'manager' then array['dashboard', 'calendar', 'bookings', 'customers', 'payments',
                              'venues', 'staff', 'reports']
    when 'front_desk' then array['dashboard', 'calendar', 'bookings', 'customers', 'payments']
    when 'coach' then array['dashboard', 'calendar']
    else array[]::text[]
  end;
$$;

create or replace function public.has_permission(p_tenant uuid, p_permission text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select public.is_platform_admin()
    or coalesce(p_permission = any (public.role_permissions(public.staff_role(p_tenant))), false);
$$;

create or replace function public.is_tenant_member(p_tenant uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select public.is_platform_admin() or public.staff_role(p_tenant) is not null;
$$;

comment on function public.has_permission(uuid, text) is
  'True for platform admins, or an active staff member whose role grants '
  'the permission (see role_permissions).';

-- ---------------------------------------------------------------------------
-- Staff guard rails: nobody makes themselves owner, and the owner can't
-- be removed or demoted from the app. auth.uid() IS NULL means a trusted
-- server context (SQL Editor, migrations, seed), which is allowed.
-- ---------------------------------------------------------------------------
create or replace function public.guard_staff_owner()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is null or public.is_platform_admin() then
    return coalesce(new, old);
  end if;

  if tg_op = 'DELETE' then
    if old.role = 'owner' then
      raise exception 'The owner can''t be removed.' using errcode = 'P0001';
    end if;
    return old;
  end if;

  if tg_op = 'INSERT' and new.role = 'owner' then
    raise exception 'Only Sideline can add an owner.' using errcode = 'P0001';
  end if;
  if tg_op = 'UPDATE' then
    if old.role = 'owner' and new.role <> 'owner' then
      raise exception 'The owner''s role can''t be changed here.' using errcode = 'P0001';
    end if;
    if old.role <> 'owner' and new.role = 'owner' then
      raise exception 'Only Sideline can make someone an owner.' using errcode = 'P0001';
    end if;
    if old.role = 'owner' and new.status <> 'active' then
      raise exception 'The owner can''t be disabled.' using errcode = 'P0001';
    end if;
    if new.email is distinct from old.email or new.user_id is distinct from old.user_id then
      raise exception 'Email and login can''t be changed here.' using errcode = 'P0001';
    end if;
  end if;
  return new;
end;
$$;

create trigger guard_staff_owner
  before insert or update or delete on public.staff_members
  for each row execute function public.guard_staff_owner();

-- ===========================================================================
-- 20261101100200_billing.sql
-- ===========================================================================

-- Purpose: what each business pays Sideline. One subscription per
-- tenant; invoices are its billing history. Changes go through
-- change_plan() / set_cancel_at_period_end() / mark_invoice_paid()
-- (see the account functions migration), never direct writes from the app.

create table public.subscriptions (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null unique references public.tenants (id) on delete cascade,
  plan_id text not null references public.plans (id),
  status text not null default 'trialing'
    check (status in ('active', 'trialing', 'past_due', 'cancelled')),
  billing_cycle text not null default 'monthly' check (billing_cycle in ('monthly', 'annual')),
  started_at date not null default current_date,
  current_period_start date not null default current_date,
  current_period_end date not null,
  trial_ends_at date,
  cancel_at_period_end boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint subscriptions_period_order check (current_period_end > current_period_start),
  constraint subscriptions_trial_has_end check (status <> 'trialing' or trial_ends_at is not null)
);

create index subscriptions_plan_id_idx on public.subscriptions (plan_id);

create trigger set_subscriptions_updated_at
  before update on public.subscriptions
  for each row execute function public.set_updated_at();

create sequence public.invoice_number_seq start 1040;

create table public.invoices (
  id uuid primary key default gen_random_uuid(),
  number text not null unique default ('SL-' || nextval('public.invoice_number_seq')),
  tenant_id uuid not null references public.tenants (id) on delete cascade,
  subscription_id uuid not null references public.subscriptions (id) on delete cascade,
  plan_id text not null references public.plans (id),
  amount_centavos integer not null check (amount_centavos >= 0),
  status text not null default 'open' check (status in ('paid', 'open', 'overdue', 'void')),
  issued_at date not null default current_date,
  due_at date not null,
  paid_at date,
  created_at timestamptz not null default now(),
  constraint invoices_paid_has_date check (status <> 'paid' or paid_at is not null)
);

create index invoices_tenant_id_idx on public.invoices (tenant_id, issued_at desc);
create index invoices_status_idx on public.invoices (status);

-- ===========================================================================
-- 20261101100300_venues.sql
-- ===========================================================================

-- Purpose: each tenant's locations and courts, and plan-limit enforcement.
--
-- Composite foreign keys (child.parent_id, child.tenant_id) -> parent(id,
-- tenant_id) make it structurally impossible for a court to point at
-- another tenant's location (or a booking at another tenant's court),
-- whatever the application sends.

create table public.locations (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants (id) on delete cascade,
  name text not null check (char_length(name) between 1 and 100),
  slug text not null check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  address text not null default '' check (char_length(address) <= 200),
  city text not null default '' check (char_length(city) <= 100),
  phone text not null default '' check (char_length(phone) <= 30),
  -- Hours of the business day; close_hour may pass midnight (25 = 1 AM).
  open_hour smallint not null check (open_hour between 0 and 23),
  close_hour smallint not null check (close_hour between 1 and 30),
  status text not null default 'active' check (status in ('active', 'inactive')),
  amenities text[] not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint locations_hours_order check (close_hour > open_hour),
  constraint locations_tenant_slug_key unique (tenant_id, slug),
  constraint locations_id_tenant_key unique (id, tenant_id)
);

create trigger set_locations_updated_at
  before update on public.locations
  for each row execute function public.set_updated_at();

create table public.courts (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants (id) on delete cascade,
  location_id uuid not null,
  name text not null check (char_length(name) between 1 and 60),
  type text not null default 'outdoor' check (type in ('indoor', 'outdoor', 'covered')),
  surface text not null default '' check (char_length(surface) <= 60),
  hourly_rate_centavos integer not null check (hourly_rate_centavos > 0),
  peak_rate_centavos integer not null check (peak_rate_centavos > 0),
  status text not null default 'active' check (status in ('active', 'maintenance', 'inactive')),
  features text[] not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint courts_location_fkey foreign key (location_id, tenant_id)
    references public.locations (id, tenant_id) on delete cascade,
  constraint courts_id_tenant_key unique (id, tenant_id),
  constraint courts_id_location_key unique (id, location_id)
);

create index courts_location_id_idx on public.courts (location_id);

create trigger set_courts_updated_at
  before update on public.courts
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Plan limits: adding one more location / court / active staff seat than
-- the tenant's plan allows is rejected here, so the limit holds even if a
-- request skips the UI. The subscription row is locked first so two
-- simultaneous inserts can't both squeeze under the limit.
-- ---------------------------------------------------------------------------
create or replace function public.enforce_plan_limit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_key text := tg_argv[0];
  v_plan_name text;
  v_limit integer;
  v_used integer;
  v_label text;
begin
  -- Re-enabling a disabled staff member takes a seat again; other updates don't.
  if tg_op = 'UPDATE' then
    if v_key <> 'staff' or old.status <> 'disabled' or new.status = 'disabled' then
      return new;
    end if;
  end if;

  select p.name,
         case v_key
           when 'locations' then p.limit_locations
           when 'courts' then p.limit_courts
           when 'staff' then p.limit_staff
         end
    into v_plan_name, v_limit
  from public.subscriptions s
  join public.plans p on p.id = s.plan_id
  where s.tenant_id = new.tenant_id
  for update of s;

  if v_limit is null then
    return new;
  end if;

  if v_key = 'locations' then
    select count(*) into v_used from public.locations where tenant_id = new.tenant_id;
    v_label := 'locations';
  elsif v_key = 'courts' then
    select count(*) into v_used from public.courts where tenant_id = new.tenant_id;
    v_label := 'courts';
  else
    select count(*) into v_used
    from public.staff_members
    where tenant_id = new.tenant_id and status <> 'disabled' and id <> new.id;
    v_label := 'staff seats';
  end if;

  if v_used >= v_limit then
    raise exception 'Your % plan includes % %. Upgrade to add more.', v_plan_name, v_limit, v_label
      using errcode = 'P0001', hint = 'limit_reached';
  end if;
  return new;
end;
$$;

create trigger enforce_location_limit
  before insert on public.locations
  for each row execute function public.enforce_plan_limit('locations');

create trigger enforce_court_limit
  before insert on public.courts
  for each row execute function public.enforce_plan_limit('courts');

create trigger enforce_staff_limit
  before insert or update of status on public.staff_members
  for each row execute function public.enforce_plan_limit('staff');

-- ===========================================================================
-- 20261101100400_customers_bookings_payments.sql
-- ===========================================================================

-- Purpose: players (per tenant), their court bookings and payments.
--
-- Bookings are stored the way the app thinks about them — a business
-- date, a start hour and a length in hours — and a trigger derives the
-- real starts_at/ends_at instants in the tenant's timezone. The exclusion
-- constraint runs on those instants, so a court can never be booked twice
-- for overlapping time, including slots that run past midnight.

-- ---------------------------------------------------------------------------
-- Customers
-- ---------------------------------------------------------------------------
create table public.customers (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants (id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 2 and 100 and name !~ '[<>]'),
  email text not null default '' check (email = '' or (email ~ '^\S+@\S+\.\S+$' and char_length(email) <= 254)),
  phone text not null check (char_length(public.phone_key(phone)) = 10),
  tags text[] not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint customers_id_tenant_key unique (id, tenant_id)
);

-- One customer record per phone number per business.
create unique index customers_tenant_phone_key on public.customers (tenant_id, public.phone_key(phone));
create index customers_tenant_email_idx on public.customers (tenant_id, lower(email)) where email <> '';

create trigger set_customers_updated_at
  before update on public.customers
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Bookings
-- ---------------------------------------------------------------------------
create table public.bookings (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants (id) on delete cascade,
  location_id uuid not null,
  court_id uuid not null,
  customer_id uuid not null,
  -- Shared by bookings made together ("Add date"); they also share `reference`.
  group_id uuid,
  reference text not null check (reference ~ '^[A-Z]{1,2}-[A-Z0-9]{4,10}$'),
  business_date date not null,
  start_hour smallint not null check (start_hour between 0 and 29),
  duration_hours smallint not null check (duration_hours between 1 and 12),
  -- Derived by bookings_set_times(); don't write these directly.
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  status text not null default 'confirmed'
    check (status in ('pending', 'confirmed', 'completed', 'cancelled', 'no_show')),
  payment_status text not null default 'unpaid' check (payment_status in ('unpaid', 'paid', 'refunded')),
  amount_centavos integer not null check (amount_centavos >= 0),
  players smallint not null default 4 check (players between 1 and 8),
  source text not null default 'online' check (source in ('online', 'walk_in', 'phone')),
  notes text not null default '' check (char_length(notes) <= 500),
  -- Unpaid online holds are released after this (see expire_stale_holds()).
  hold_expires_at timestamptz,
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint bookings_location_fkey foreign key (location_id, tenant_id)
    references public.locations (id, tenant_id),
  constraint bookings_court_fkey foreign key (court_id, tenant_id)
    references public.courts (id, tenant_id),
  constraint bookings_court_location_fkey foreign key (court_id, location_id)
    references public.courts (id, location_id),
  constraint bookings_customer_fkey foreign key (customer_id, tenant_id)
    references public.customers (id, tenant_id),
  constraint bookings_id_tenant_key unique (id, tenant_id),
  constraint bookings_valid_range check (ends_at > starts_at)
);

comment on table public.bookings is
  'Court bookings. Created only through create_booking_group(); staff '
  'changes go through the booking functions. Courts and locations with '
  'booking history can''t be deleted (set them inactive instead).';

create index bookings_tenant_date_idx on public.bookings (tenant_id, business_date);
create index bookings_location_date_idx on public.bookings (location_id, business_date);
create index bookings_court_starts_idx on public.bookings (court_id, starts_at);
create index bookings_customer_idx on public.bookings (customer_id);
create index bookings_tenant_reference_idx on public.bookings (tenant_id, reference);
create index bookings_group_idx on public.bookings (group_id) where group_id is not null;

create or replace function public.bookings_set_times()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_tz text;
begin
  select timezone into v_tz from public.tenants where id = new.tenant_id;
  new.starts_at := (new.business_date::timestamp + make_interval(hours => new.start_hour))
                   at time zone coalesce(v_tz, 'Asia/Manila');
  new.ends_at := new.starts_at + make_interval(hours => new.duration_hours);
  return new;
end;
$$;

create trigger bookings_set_times
  before insert or update of business_date, start_hour, duration_hours, tenant_id
  on public.bookings
  for each row execute function public.bookings_set_times();

create trigger set_bookings_updated_at
  before update on public.bookings
  for each row execute function public.set_updated_at();

-- THE double-booking guard: enforced by the index at insert/update time,
-- so two simultaneous requests for the same court and time can't both
-- succeed. Only bookings that occupy the court count.
alter table public.bookings
  add constraint bookings_no_overlap
  exclude using gist (
    court_id with =,
    tstzrange(starts_at, ends_at, '[)') with &&
  )
  where (status in ('pending', 'confirmed', 'completed'));

-- ---------------------------------------------------------------------------
-- Payments (one row per booking; a multi-date booking's rows share the
-- provider `reference`, since one transfer paid for all of them)
-- ---------------------------------------------------------------------------
create table public.payments (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants (id) on delete cascade,
  booking_id uuid not null,
  customer_id uuid not null,
  amount_centavos integer not null check (amount_centavos >= 0),
  method text not null check (method in ('gcash', 'maya', 'card', 'bank_transfer', 'cash')),
  status text not null check (status in ('paid', 'pending', 'refunded', 'failed')),
  reference text not null default '' check (char_length(reference) <= 100),
  recorded_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint payments_booking_fkey foreign key (booking_id, tenant_id)
    references public.bookings (id, tenant_id) on delete cascade,
  constraint payments_customer_fkey foreign key (customer_id, tenant_id)
    references public.customers (id, tenant_id)
);

create index payments_tenant_created_idx on public.payments (tenant_id, created_at desc);
create index payments_booking_idx on public.payments (booking_id);
create index payments_pending_idx on public.payments (tenant_id) where status = 'pending';

create trigger set_payments_updated_at
  before update on public.payments
  for each row execute function public.set_updated_at();

-- ===========================================================================
-- 20261101100500_analytics_tables.sql
-- ===========================================================================

-- Purpose: analytics that can't be derived from bookings — monthly
-- booking-site traffic per tenant (filled by a page-view collector
-- later; seeded for demos) — and the platform activity feed shown in the
-- Super Admin console.

create table public.page_view_stats (
  tenant_id uuid not null references public.tenants (id) on delete cascade,
  -- First day of the month.
  month date not null check (extract(day from month) = 1),
  page_views integer not null default 0 check (page_views >= 0),
  booking_starts integer not null default 0 check (booking_starts >= 0),
  bookings_completed integer not null default 0 check (bookings_completed >= 0),
  primary key (tenant_id, month)
);

create table public.platform_activity (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants (id) on delete cascade,
  kind text not null
    check (kind in ('signup', 'upgrade', 'downgrade', 'payment_failed', 'payment', 'suspended', 'support')),
  message text not null check (char_length(message) <= 300),
  actor_id uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);

create index platform_activity_created_idx on public.platform_activity (created_at desc);
create index platform_activity_tenant_idx on public.platform_activity (tenant_id, created_at desc);

-- Internal helper for the functions that log activity.
create or replace function public.log_activity(p_tenant uuid, p_kind text, p_message text)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.platform_activity (tenant_id, kind, message, actor_id)
  values (p_tenant, p_kind, p_message, (select auth.uid()));
$$;

-- ===========================================================================
-- 20261101100600_rls_and_grants.sql
-- ===========================================================================

-- Purpose: row-level security and table privileges — the real tenant
-- isolation boundary (route guards in the app are only a convenience).
--
-- Approach: start from nothing (revoke everything from the API roles),
-- then grant each role exactly what its RLS policies allow. Column-level
-- grants keep sensitive columns (tenant status, staff user_id, …)
-- writable only through SECURITY DEFINER functions. match-pickleball
-- found that hosted Supabase needs these grants spelled out, so nothing
-- here relies on default privileges.

revoke all on all tables in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;
grant usage on schema public to anon, authenticated;

alter table public.platform_admins enable row level security;
alter table public.plans enable row level security;
alter table public.tenants enable row level security;
alter table public.booking_rules enable row level security;
alter table public.staff_members enable row level security;
alter table public.subscriptions enable row level security;
alter table public.invoices enable row level security;
alter table public.locations enable row level security;
alter table public.courts enable row level security;
alter table public.customers enable row level security;
alter table public.bookings enable row level security;
alter table public.payments enable row level security;
alter table public.page_view_stats enable row level security;
alter table public.platform_activity enable row level security;

-- ---------------------------------------------------------------------------
-- Public (booking site) data: plans, tenant profiles, rules, venues
-- ---------------------------------------------------------------------------
create policy plans_select on public.plans
  for select to anon, authenticated
  using (is_public or public.is_platform_admin());
create policy plans_update_admin on public.plans
  for update to authenticated
  using (public.is_platform_admin()) with check (public.is_platform_admin());

create policy tenants_select on public.tenants
  for select to anon, authenticated using (true);
create policy tenants_update on public.tenants
  for update to authenticated
  using (public.has_permission(id, 'settings')) with check (public.has_permission(id, 'settings'));

create policy booking_rules_select on public.booking_rules
  for select to anon, authenticated using (true);
create policy booking_rules_update on public.booking_rules
  for update to authenticated
  using (public.has_permission(tenant_id, 'settings'))
  with check (public.has_permission(tenant_id, 'settings'));

create policy locations_select on public.locations
  for select to anon, authenticated using (true);
create policy locations_insert on public.locations
  for insert to authenticated with check (public.has_permission(tenant_id, 'venues'));
create policy locations_update on public.locations
  for update to authenticated
  using (public.has_permission(tenant_id, 'venues')) with check (public.has_permission(tenant_id, 'venues'));
create policy locations_delete on public.locations
  for delete to authenticated using (public.has_permission(tenant_id, 'venues'));

create policy courts_select on public.courts
  for select to anon, authenticated using (true);
create policy courts_insert on public.courts
  for insert to authenticated with check (public.has_permission(tenant_id, 'venues'));
create policy courts_update on public.courts
  for update to authenticated
  using (public.has_permission(tenant_id, 'venues')) with check (public.has_permission(tenant_id, 'venues'));
create policy courts_delete on public.courts
  for delete to authenticated using (public.has_permission(tenant_id, 'venues'));

grant select on public.plans, public.tenants, public.booking_rules, public.locations, public.courts
  to anon, authenticated;

grant update (name, description, monthly_price_centavos, annual_price_centavos, limit_locations,
              limit_courts, limit_staff, limit_bookings_per_month, features, highlighted, is_public)
  on public.plans to authenticated;
grant update (name, legal_name, owner_name, owner_email, phone, city, about,
              brand_primary, brand_accent, brand_monogram, brand_tagline)
  on public.tenants to authenticated;
grant update on public.booking_rules to authenticated;
grant insert, update, delete on public.locations, public.courts to authenticated;

-- ---------------------------------------------------------------------------
-- Tenant-private data (signed-in staff of that tenant, or platform admins)
-- ---------------------------------------------------------------------------
create policy platform_admins_select on public.platform_admins
  for select to authenticated
  using (user_id = (select auth.uid()) or public.is_platform_admin());

create policy staff_select on public.staff_members
  for select to authenticated using (public.is_tenant_member(tenant_id));
create policy staff_insert on public.staff_members
  for insert to authenticated with check (public.has_permission(tenant_id, 'staff'));
create policy staff_update on public.staff_members
  for update to authenticated
  using (public.has_permission(tenant_id, 'staff')) with check (public.has_permission(tenant_id, 'staff'));
create policy staff_delete on public.staff_members
  for delete to authenticated using (public.has_permission(tenant_id, 'staff'));

create policy subscriptions_select on public.subscriptions
  for select to authenticated using (public.is_tenant_member(tenant_id));

create policy invoices_select on public.invoices
  for select to authenticated using (public.has_permission(tenant_id, 'billing'));

create policy customers_select on public.customers
  for select to authenticated using (public.has_permission(tenant_id, 'customers'));
create policy customers_insert on public.customers
  for insert to authenticated with check (public.has_permission(tenant_id, 'customers'));
create policy customers_update on public.customers
  for update to authenticated
  using (public.has_permission(tenant_id, 'customers'))
  with check (public.has_permission(tenant_id, 'customers'));

-- Every member sees the schedule (coaches use the calendar too).
create policy bookings_select on public.bookings
  for select to authenticated using (public.is_tenant_member(tenant_id));

create policy payments_select on public.payments
  for select to authenticated using (public.has_permission(tenant_id, 'payments'));

create policy page_view_stats_select on public.page_view_stats
  for select to authenticated using (public.has_permission(tenant_id, 'reports'));

create policy platform_activity_select on public.platform_activity
  for select to authenticated using (public.is_platform_admin());

grant select on public.platform_admins, public.staff_members, public.subscriptions,
                public.invoices, public.customers, public.bookings, public.payments,
                public.page_view_stats, public.platform_activity
  to authenticated;

-- Staff: invited by insert (status/user_id stay server-controlled).
grant insert (tenant_id, name, email, phone, role, location_ids) on public.staff_members to authenticated;
grant update (name, phone, role, location_ids, status) on public.staff_members to authenticated;
grant delete on public.staff_members to authenticated;

grant insert (tenant_id, name, email, phone, tags) on public.customers to authenticated;
grant update (name, email, phone, tags) on public.customers to authenticated;

-- Deliberately not granted: any write on subscriptions, invoices,
-- bookings, payments, platform_admins, page_view_stats or
-- platform_activity. Those change only through the functions in the
-- following migrations, which check permissions themselves.

-- ===========================================================================
-- 20261101100700_views.sql
-- ===========================================================================

-- Purpose: read views the dashboard lists use (BookingRow, CustomerSummary
-- and PaymentRow in the app). security_invoker = true makes each view run
-- with the caller's privileges, so the underlying tables' RLS still
-- decides which rows anyone sees.

create view public.booking_rows
with (security_invoker = true) as
select
  b.*,
  c.name as customer_name,
  c.phone as customer_phone,
  ct.name as court_name,
  l.name as location_name
from public.bookings b
join public.customers c on c.id = b.customer_id
join public.courts ct on ct.id = b.court_id
join public.locations l on l.id = b.location_id;

create view public.customer_summaries
with (security_invoker = true) as
select
  c.*,
  count(b.id) filter (where b.status <> 'cancelled')::integer as booking_count,
  coalesce(sum(b.amount_centavos) filter (where b.payment_status = 'paid'), 0)::integer as total_spent_centavos,
  max(b.business_date) filter (
    where b.status = 'completed' and b.business_date <= public.local_today()
  ) as last_visit,
  count(b.id) filter (where b.status = 'no_show')::integer as no_show_count
from public.customers c
left join public.bookings b on b.customer_id = c.id
group by c.id;

create view public.payment_rows
with (security_invoker = true) as
select
  p.*,
  b.reference as booking_reference,
  b.business_date as booking_date,
  b.location_id,
  c.name as customer_name
from public.payments p
join public.bookings b on b.id = p.booking_id
join public.customers c on c.id = p.customer_id;

grant select on public.booking_rows, public.customer_summaries, public.payment_rows to authenticated;

-- ===========================================================================
-- 20261101100800_booking_functions.sql
-- ===========================================================================

-- Purpose: the booking engine. Every write to bookings/payments happens
-- here, in SECURITY DEFINER functions that check the caller's permission
-- themselves (the tables have no write grants for API roles).
--
-- Mirrors src/services/bookingService.ts + paymentService.ts so the app
-- behaves the same on mock data and on Supabase.

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------

-- Price of a booking in centavos: each hour is peak or off-peak on its own
-- (peak can start mid-booking). Mirrors src/utils/pricing.ts.
create or replace function public.booking_price(
  p_court_id uuid, p_date date, p_start_hour integer, p_duration_hours integer
)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(sum(
    case
      when h >= r.peak_start_hour
       and (r.peak_days = 'all'
            or (r.peak_days = 'weekends') = (extract(isodow from p_date) in (6, 7)))
      then c.peak_rate_centavos
      else c.hourly_rate_centavos
    end
  ), 0)::integer
  from public.courts c
  join public.booking_rules r on r.tenant_id = c.tenant_id
  cross join generate_series(p_start_hour, p_start_hour + p_duration_hours - 1) as h
  where c.id = p_court_id;
$$;

-- Releases unpaid online holds whose time ran out and that have no
-- payment waiting for review. Called at the start of availability and
-- booking requests, so no scheduled job is needed (same approach as
-- match-pickleball, whose free hosting tier has no reliable cron).
create or replace function public.expire_stale_holds()
returns void
language sql
security definer
set search_path = ''
as $$
  update public.bookings b
  set status = 'cancelled', hold_expires_at = null
  where b.status = 'pending'
    and b.hold_expires_at is not null
    and b.hold_expires_at < now()
    and not exists (
      select 1 from public.payments p
      where p.booking_id = b.id and p.status in ('pending', 'paid')
    );
$$;

-- "RP-7K2Q9C": tenant monogram + random hex, unique within the tenant.
create or replace function public.generate_booking_reference(p_tenant_id uuid)
returns text
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_prefix text;
  v_reference text;
begin
  select coalesce(nullif(upper(left(regexp_replace(brand_monogram, '[^A-Za-z]', '', 'g'), 2)), ''), 'SL')
    into v_prefix
  from public.tenants where id = p_tenant_id;

  loop
    v_reference := coalesce(v_prefix, 'SL') || '-' || upper(substr(md5(gen_random_uuid()::text), 1, 6));
    exit when not exists (
      select 1 from public.bookings where tenant_id = p_tenant_id and reference = v_reference
    );
  end loop;
  return v_reference;
end;
$$;

create or replace function public.provider_reference(p_method text)
returns text
language sql
volatile
set search_path = ''
as $$
  select upper(left(p_method, 2)) || (floor(random() * 90000000) + 10000000)::bigint::text;
$$;

-- Loads a booking's tenant and checks the caller may act on it.
create or replace function public.require_booking_permission(p_booking_id uuid, p_permission text)
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_tenant uuid;
begin
  select tenant_id into v_tenant from public.bookings where id = p_booking_id;
  if v_tenant is null then
    raise exception 'Booking not found' using errcode = 'P0002';
  end if;
  if not public.has_permission(v_tenant, p_permission) then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;
  return v_tenant;
end;
$$;

-- ---------------------------------------------------------------------------
-- Public: availability and booking
-- ---------------------------------------------------------------------------

-- Which hours are taken on each court of a location on a business date.
-- Returns no customer data, so the public booking site can call it.
create or replace function public.get_availability(p_location_id uuid, p_date date)
returns table (court_id uuid, hour integer)
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.expire_stale_holds();
  return query
    select b.court_id, gs.h::integer
    from public.bookings b
    cross join generate_series(b.start_hour, b.start_hour + b.duration_hours - 1) as gs (h)
    where b.location_id = p_location_id
      and b.business_date = p_date
      and b.status in ('pending', 'confirmed', 'completed');
end;
$$;

-- Books one or more dates/times together (match-pickleball's "Add date"):
-- every slot is validated first, then all are inserted in this one
-- transaction under one reference. Any failure — including the overlap
-- constraint catching a simultaneous booking — creates nothing.
--
-- p_slots: [{"courtId": uuid, "date": "YYYY-MM-DD", "startHour": int, "durationHours": int}]
--
-- Public (online) callers can't mark a booking as paid: a payment they
-- report is recorded as 'pending' for staff to verify (GCash/transfer
-- proofs). Instant card/Maya confirmation will come from the payment
-- provider's webhook once one is integrated. Staff (source walk_in /
-- phone) may record a payment as received.
create or replace function public.create_booking_group(
  p_tenant_id uuid,
  p_slots jsonb,
  p_customer_name text,
  p_customer_phone text,
  p_customer_email text default '',
  p_players integer default 4,
  p_notes text default '',
  p_source text default 'online',
  p_payment_method text default null,
  p_payment_pending boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant public.tenants;
  v_rules public.booking_rules;
  v_is_staff boolean := public.has_permission(p_tenant_id, 'bookings');
  v_today date;
  v_now_hour integer;
  v_count integer;
  v_slot record;
  v_court record;
  v_limit integer;
  v_month record;
  v_customer_id uuid;
  v_method text := nullif(p_payment_method, '');
  v_paid_now boolean;
  v_status text;
  v_reference text;
  v_group_id uuid;
  v_payment_reference text;
  v_booking_id uuid;
  v_amount integer;
  v_total integer := 0;
  v_ids uuid[] := '{}';
begin
  perform public.expire_stale_holds();

  select * into v_tenant from public.tenants where id = p_tenant_id;
  if not found then
    raise exception 'Business not found' using errcode = 'P0002';
  end if;
  if v_tenant.status in ('suspended', 'cancelled') then
    raise exception '% is not taking bookings at the moment.', v_tenant.name using errcode = 'P0001';
  end if;
  if p_source not in ('online', 'walk_in', 'phone') then
    raise exception 'Unknown booking source' using errcode = '22023';
  end if;
  if p_source <> 'online' and not v_is_staff then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;

  select * into v_rules from public.booking_rules where tenant_id = p_tenant_id;
  v_today := public.local_today(v_tenant.timezone);
  v_now_hour := extract(hour from now() at time zone v_tenant.timezone)::integer;

  -- Payment: online cash means "pay at the venue" (only when allowed).
  if p_source = 'online' and not v_is_staff then
    if v_method is not null and not (v_method = any (v_rules.payment_methods)) then
      raise exception 'That payment method isn''t accepted here.' using errcode = 'P0001';
    end if;
    if v_method = 'cash' then
      if v_rules.require_prepayment then
        raise exception 'This business needs payment before the booking is confirmed.' using errcode = 'P0001';
      end if;
      v_method := null;
    end if;
    v_paid_now := false;
  else
    v_paid_now := v_method is not null and not coalesce(p_payment_pending, false);
  end if;

  -- Customer details
  if char_length(btrim(coalesce(p_customer_name, ''))) < 2 or p_customer_name ~ '[<>]' then
    raise exception 'Please enter your name.' using errcode = 'P0001';
  end if;
  if char_length(public.phone_key(p_customer_phone)) <> 10 then
    raise exception 'Please enter a valid mobile number.' using errcode = 'P0001';
  end if;
  if char_length(coalesce(p_notes, '')) > 500 then
    raise exception 'Notes are too long (500 characters max).' using errcode = 'P0001';
  end if;

  -- Slots
  if jsonb_typeof(p_slots) <> 'array' then
    raise exception 'Pick at least one time.' using errcode = '22023';
  end if;
  v_count := jsonb_array_length(p_slots);
  if v_count = 0 then
    raise exception 'Pick at least one time.' using errcode = 'P0001';
  end if;
  if v_count > 7 then
    raise exception 'One booking can cover up to 7 dates.' using errcode = 'P0001';
  end if;

  for v_slot in
    select (s->>'courtId')::uuid as court_id,
           (s->>'date')::date as business_date,
           (s->>'startHour')::integer as start_hour,
           (s->>'durationHours')::integer as duration_hours
    from jsonb_array_elements(p_slots) as s
  loop
    select c.status, c.name, l.status as location_status, l.open_hour, l.close_hour
      into v_court
    from public.courts c
    join public.locations l on l.id = c.location_id
    where c.id = v_slot.court_id and c.tenant_id = p_tenant_id;
    if not found then
      raise exception 'Court not found' using errcode = 'P0002';
    end if;
    if v_court.status <> 'active' or v_court.location_status <> 'active' then
      raise exception '% is not open for bookings right now.', v_court.name using errcode = 'P0001';
    end if;
    if v_slot.duration_hours < 1
       or v_slot.start_hour < v_court.open_hour
       or v_slot.start_hour + v_slot.duration_hours > v_court.close_hour then
      raise exception 'That time is outside opening hours.' using errcode = 'P0001';
    end if;
    if p_source = 'online' and not v_is_staff then
      if v_slot.duration_hours * 60 < v_rules.min_duration_minutes
         or v_slot.duration_hours * 60 > v_rules.max_duration_minutes then
        raise exception 'That booking length is not allowed.' using errcode = 'P0001';
      end if;
      if v_slot.business_date > v_today + v_rules.advance_booking_days then
        raise exception 'Bookings open % days ahead.', v_rules.advance_booking_days using errcode = 'P0001';
      end if;
      if v_slot.business_date < v_today
         or (v_slot.business_date = v_today and v_slot.start_hour <= v_now_hour) then
        raise exception 'That time has already passed.' using errcode = 'P0001';
      end if;
    end if;
  end loop;

  if exists (
    select 1
    from jsonb_array_elements(p_slots) with ordinality as a (s, i)
    join jsonb_array_elements(p_slots) with ordinality as b (s, j) on a.i < b.j
    where a.s->>'courtId' = b.s->>'courtId'
      and a.s->>'date' = b.s->>'date'
      and (a.s->>'startHour')::integer < (b.s->>'startHour')::integer + (b.s->>'durationHours')::integer
      and (b.s->>'startHour')::integer < (a.s->>'startHour')::integer + (a.s->>'durationHours')::integer
  ) then
    raise exception 'Two of the picked times overlap on the same court.' using errcode = 'P0001';
  end if;

  -- Monthly booking limit of the plan
  select p.limit_bookings_per_month into v_limit
  from public.subscriptions s join public.plans p on p.id = s.plan_id
  where s.tenant_id = p_tenant_id;
  if v_limit is not null then
    for v_month in
      select date_trunc('month', (s->>'date')::date)::date as month, count(*) as adding
      from jsonb_array_elements(p_slots) as s
      group by 1
    loop
      if (
        select count(*) from public.bookings
        where tenant_id = p_tenant_id and status <> 'cancelled'
          and business_date >= v_month.month
          and business_date < (v_month.month + interval '1 month')::date
      ) + v_month.adding > v_limit then
        raise exception 'This business has reached its monthly booking limit.'
          using errcode = 'P0001', hint = 'limit_reached';
      end if;
    end loop;
  end if;

  -- Customer: one record per phone number per business
  select id into v_customer_id
  from public.customers
  where tenant_id = p_tenant_id and public.phone_key(phone) = public.phone_key(p_customer_phone);
  if v_customer_id is null then
    insert into public.customers (tenant_id, name, email, phone, tags)
    values (p_tenant_id, btrim(p_customer_name), coalesce(btrim(p_customer_email), ''),
            btrim(p_customer_phone), array['New'])
    returning id into v_customer_id;
  end if;

  v_status := case
    when p_source = 'online' and v_rules.require_prepayment and not v_paid_now then 'pending'
    else 'confirmed'
  end;
  v_reference := public.generate_booking_reference(p_tenant_id);
  v_group_id := case when v_count > 1 then gen_random_uuid() end;
  v_payment_reference := case when v_method is not null then public.provider_reference(v_method) end;

  begin
    for v_slot in
      select (s->>'courtId')::uuid as court_id,
             (s->>'date')::date as business_date,
             (s->>'startHour')::integer as start_hour,
             (s->>'durationHours')::integer as duration_hours
      from jsonb_array_elements(p_slots) as s
      order by 2, 3
    loop
      v_amount := public.booking_price(v_slot.court_id, v_slot.business_date,
                                       v_slot.start_hour, v_slot.duration_hours);
      insert into public.bookings (
        tenant_id, location_id, court_id, customer_id, group_id, reference,
        business_date, start_hour, duration_hours, status, payment_status,
        amount_centavos, players, source, notes, hold_expires_at, created_by
      )
      select p_tenant_id, c.location_id, c.id, v_customer_id, v_group_id, v_reference,
             v_slot.business_date, v_slot.start_hour, v_slot.duration_hours, v_status,
             case when v_paid_now then 'paid' else 'unpaid' end,
             v_amount, coalesce(p_players, 4), p_source, coalesce(p_notes, ''),
             case when v_status = 'pending' and v_method is null
                  then now() + make_interval(mins => v_rules.hold_minutes) end,
             (select auth.uid())
      from public.courts c where c.id = v_slot.court_id
      returning id into v_booking_id;

      if v_method is not null then
        insert into public.payments (tenant_id, booking_id, customer_id, amount_centavos,
                                     method, status, reference, recorded_by)
        values (p_tenant_id, v_booking_id, v_customer_id, v_amount, v_method,
                case when v_paid_now then 'paid' else 'pending' end,
                v_payment_reference, (select auth.uid()));
      end if;

      v_total := v_total + v_amount;
      v_ids := v_ids || v_booking_id;
    end loop;
  exception
    when exclusion_violation then
      raise exception 'That time overlaps another booking on this court.' using errcode = 'P0001';
  end;

  return jsonb_build_object('reference', v_reference, 'total', v_total, 'bookingIds', to_jsonb(v_ids));
end;
$$;

-- Public "find my booking": reference plus the phone number used. Returns
-- every date/time under that reference (empty when nothing matches).
create or replace function public.lookup_booking(p_tenant_id uuid, p_reference text, p_phone text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', b.id,
    'reference', b.reference,
    'groupId', b.group_id,
    'date', b.business_date,
    'startHour', b.start_hour,
    'durationHours', b.duration_hours,
    'status', b.status,
    'paymentStatus', b.payment_status,
    'amount', b.amount_centavos,
    'courtName', ct.name,
    'locationName', l.name,
    'customerName', c.name
  ) order by b.business_date, b.start_hour), '[]'::jsonb)
  from public.bookings b
  join public.customers c on c.id = b.customer_id
  join public.courts ct on ct.id = b.court_id
  join public.locations l on l.id = b.location_id
  where b.tenant_id = p_tenant_id
    and b.reference = upper(btrim(p_reference))
    and char_length(public.phone_key(p_phone)) = 10
    and public.phone_key(c.phone) = public.phone_key(p_phone);
$$;

-- ---------------------------------------------------------------------------
-- Staff: booking changes (permission 'bookings')
-- ---------------------------------------------------------------------------
create or replace function public.set_booking_status(p_booking_id uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_booking_permission(p_booking_id, 'bookings');
  if p_status not in ('confirmed', 'completed', 'no_show') then
    raise exception 'Use cancel_booking() to cancel.' using errcode = '22023';
  end if;
  update public.bookings set status = p_status, hold_expires_at = null where id = p_booking_id;
exception
  when exclusion_violation then
    raise exception 'That time overlaps another booking on this court.' using errcode = 'P0001';
end;
$$;

create or replace function public.cancel_booking(p_booking_id uuid, p_refund boolean default false)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_booking_permission(p_booking_id, 'bookings');
  update public.bookings
  set status = 'cancelled',
      hold_expires_at = null,
      payment_status = case when p_refund and payment_status = 'paid' then 'refunded' else payment_status end
  where id = p_booking_id;
  if p_refund then
    update public.payments set status = 'refunded'
    where booking_id = p_booking_id and status = 'paid';
  end if;
end;
$$;

create or replace function public.mark_booking_paid(p_booking_id uuid, p_method text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant uuid := public.require_booking_permission(p_booking_id, 'bookings');
begin
  if p_method not in ('gcash', 'maya', 'card', 'bank_transfer', 'cash') then
    raise exception 'Unknown payment method' using errcode = '22023';
  end if;
  if exists (select 1 from public.payments where booking_id = p_booking_id and status = 'pending') then
    update public.payments set status = 'paid', recorded_by = (select auth.uid())
    where booking_id = p_booking_id and status = 'pending';
  else
    insert into public.payments (tenant_id, booking_id, customer_id, amount_centavos, method,
                                 status, reference, recorded_by)
    select v_tenant, b.id, b.customer_id, b.amount_centavos, p_method, 'paid',
           public.provider_reference(p_method), (select auth.uid())
    from public.bookings b where b.id = p_booking_id;
  end if;
  update public.bookings
  set payment_status = 'paid',
      status = case when status = 'pending' then 'confirmed' else status end,
      hold_expires_at = null
  where id = p_booking_id;
end;
$$;

create or replace function public.reschedule_booking(
  p_booking_id uuid, p_court_id uuid, p_date date, p_start_hour integer, p_duration_hours integer
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant uuid := public.require_booking_permission(p_booking_id, 'bookings');
  v_court record;
begin
  select c.location_id, c.status, c.name, l.open_hour, l.close_hour into v_court
  from public.courts c join public.locations l on l.id = c.location_id
  where c.id = p_court_id and c.tenant_id = v_tenant;
  if not found then
    raise exception 'Court not found' using errcode = 'P0002';
  end if;
  if v_court.status <> 'active' then
    raise exception '% is not open for bookings right now.', v_court.name using errcode = 'P0001';
  end if;
  if p_duration_hours < 1 or p_start_hour < v_court.open_hour
     or p_start_hour + p_duration_hours > v_court.close_hour then
    raise exception 'That time is outside opening hours.' using errcode = 'P0001';
  end if;
  update public.bookings
  set court_id = p_court_id,
      location_id = v_court.location_id,
      business_date = p_date,
      start_hour = p_start_hour,
      duration_hours = p_duration_hours,
      amount_centavos = public.booking_price(p_court_id, p_date, p_start_hour, p_duration_hours)
  where id = p_booking_id;
exception
  when exclusion_violation then
    raise exception 'That time overlaps another booking on this court.' using errcode = 'P0001';
end;
$$;

-- ---------------------------------------------------------------------------
-- Staff: payment review (permission 'payments')
-- ---------------------------------------------------------------------------

-- A multi-date booking was paid with one transfer, so approving or
-- rejecting its proof applies to every pending payment in the group.
create or replace function public.review_payment(p_payment_id uuid, p_approve boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_payment public.payments;
  v_group uuid;
  v_ids uuid[];
begin
  select * into v_payment from public.payments where id = p_payment_id;
  if not found then
    raise exception 'Payment not found' using errcode = 'P0002';
  end if;
  if not public.has_permission(v_payment.tenant_id, 'payments') then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;

  select group_id into v_group from public.bookings where id = v_payment.booking_id;
  select array_agg(p.id) into v_ids
  from public.payments p
  join public.bookings b on b.id = p.booking_id
  where p.id = p_payment_id
     or (v_group is not null and b.group_id = v_group and p.status = 'pending');

  update public.payments
  set status = case when p_approve then 'paid' else 'failed' end,
      recorded_by = (select auth.uid())
  where id = any (v_ids);

  if p_approve then
    update public.bookings b
    set payment_status = 'paid',
        status = case when b.status = 'pending' then 'confirmed' else b.status end,
        hold_expires_at = null
    where b.id in (select booking_id from public.payments where id = any (v_ids));
  end if;
end;
$$;

create or replace function public.refund_payment(p_payment_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_payment public.payments;
begin
  select * into v_payment from public.payments where id = p_payment_id;
  if not found then
    raise exception 'Payment not found' using errcode = 'P0002';
  end if;
  if not public.has_permission(v_payment.tenant_id, 'payments') then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;
  update public.payments set status = 'refunded', recorded_by = (select auth.uid())
  where id = p_payment_id;
  update public.bookings set payment_status = 'refunded' where id = v_payment.booking_id;
end;
$$;

-- ===========================================================================
-- 20261101100900_account_functions.sql
-- ===========================================================================

-- Purpose: accounts and subscriptions — linking Supabase Auth users to
-- their staff invites, "who am I", plan usage and changes, invoices, and
-- onboarding/suspending businesses.

-- ---------------------------------------------------------------------------
-- Staff <-> auth users
-- ---------------------------------------------------------------------------

-- When someone signs up (or changes email), attach any staff invites for
-- that email to their account and activate them.
create or replace function public.link_staff_on_signup()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.email is null then
    return new;
  end if;
  update public.staff_members
  set user_id = new.id,
      status = case when status = 'invited' then 'active' else status end
  where lower(email) = lower(new.email) and user_id is null;
  return new;
end;
$$;

create trigger on_auth_user_link_staff
  after insert or update of email on auth.users
  for each row execute function public.link_staff_on_signup();

-- And the other way round: inviting an email that already has an account
-- links it right away.
create or replace function public.link_staff_to_existing_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid;
begin
  select id into v_user from auth.users where lower(email) = lower(new.email) limit 1;
  if v_user is not null then
    new.user_id := v_user;
    if new.status = 'invited' then
      new.status := 'active';
    end if;
  end if;
  return new;
end;
$$;

create trigger link_staff_to_existing_user
  before insert on public.staff_members
  for each row execute function public.link_staff_to_existing_user();

-- Who the signed-in user is: platform admin and/or staff memberships.
-- Also records "last active" for the staff list.
create or replace function public.my_memberships()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
begin
  if v_uid is null then
    return jsonb_build_object('isPlatformAdmin', false, 'memberships', '[]'::jsonb);
  end if;

  update public.staff_members set last_active_at = now()
  where user_id = v_uid and status = 'active';

  return jsonb_build_object(
    'isPlatformAdmin', public.is_platform_admin(),
    'memberships', coalesce((
      select jsonb_agg(jsonb_build_object(
        'staffId', s.id,
        'tenantId', t.id,
        'tenantSlug', t.slug,
        'tenantName', t.name,
        'role', s.role,
        'name', s.name,
        'email', s.email
      ) order by t.name)
      from public.staff_members s
      join public.tenants t on t.id = s.tenant_id
      where s.user_id = v_uid and s.status = 'active'
    ), '[]'::jsonb)
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- Plans and usage
-- ---------------------------------------------------------------------------
create or replace function public.compute_usage(p_tenant_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with p as (
    select pl.*
    from public.subscriptions s join public.plans pl on pl.id = s.plan_id
    where s.tenant_id = p_tenant_id
  ), tz as (
    select timezone from public.tenants where id = p_tenant_id
  )
  select jsonb_build_array(
    jsonb_build_object('key', 'locations',
      'used', (select count(*) from public.locations where tenant_id = p_tenant_id),
      'limit', (select limit_locations from p)),
    jsonb_build_object('key', 'courts',
      'used', (select count(*) from public.courts where tenant_id = p_tenant_id),
      'limit', (select limit_courts from p)),
    jsonb_build_object('key', 'staff',
      'used', (select count(*) from public.staff_members
               where tenant_id = p_tenant_id and status <> 'disabled'),
      'limit', (select limit_staff from p)),
    jsonb_build_object('key', 'bookingsPerMonth',
      'used', (select count(*) from public.bookings
               where tenant_id = p_tenant_id and status <> 'cancelled'
                 and date_trunc('month', business_date)
                     = date_trunc('month', public.local_today((select timezone from tz)))),
      'limit', (select limit_bookings_per_month from p))
  );
$$;

create or replace function public.tenant_usage(p_tenant_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_tenant_member(p_tenant_id) then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;
  return public.compute_usage(p_tenant_id);
end;
$$;

-- Switch plan / billing cycle. Plans whose limits are below current
-- usage are refused; non-public plans (Enterprise) are admin-only.
create or replace function public.change_plan(p_tenant_id uuid, p_plan_id text, p_billing_cycle text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_sub public.subscriptions;
  v_old public.plans;
  v_new public.plans;
  v_usage jsonb := public.compute_usage(p_tenant_id);
  v_item jsonb;
  v_limit integer;
  v_today date := public.local_today();
begin
  if not public.has_permission(p_tenant_id, 'billing') then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;
  if p_billing_cycle not in ('monthly', 'annual') then
    raise exception 'Unknown billing cycle' using errcode = '22023';
  end if;
  select * into v_sub from public.subscriptions where tenant_id = p_tenant_id for update;
  if not found then
    raise exception 'No subscription for this business' using errcode = 'P0002';
  end if;
  select * into v_old from public.plans where id = v_sub.plan_id;
  select * into v_new from public.plans where id = p_plan_id;
  if not found then
    raise exception 'Plan not found' using errcode = 'P0002';
  end if;
  if not v_new.is_public and not public.is_platform_admin() then
    raise exception 'Contact Sideline to switch to the % plan.', v_new.name using errcode = 'P0001';
  end if;

  for v_item in select * from jsonb_array_elements(v_usage) loop
    continue when v_item->>'key' = 'bookingsPerMonth';
    v_limit := case v_item->>'key'
      when 'locations' then v_new.limit_locations
      when 'courts' then v_new.limit_courts
      when 'staff' then v_new.limit_staff
    end;
    if v_limit is not null and (v_item->>'used')::integer > v_limit then
      raise exception 'Can''t switch: you''re using % % and the % plan allows %.',
        v_item->>'used', v_item->>'key', v_new.name, v_limit using errcode = 'P0001';
    end if;
  end loop;

  update public.subscriptions
  set plan_id = p_plan_id,
      billing_cycle = p_billing_cycle,
      cancel_at_period_end = false,
      status = case when status = 'trialing' then status else 'active' end,
      current_period_start = case when status = 'trialing' then current_period_start else v_today end,
      current_period_end = case
        when status = 'trialing' then current_period_end
        when p_billing_cycle = 'annual' then (v_today + interval '1 year')::date
        else (v_today + interval '1 month')::date
      end
  where id = v_sub.id;

  perform public.log_activity(
    p_tenant_id,
    case when v_new.monthly_price_centavos >= v_old.monthly_price_centavos then 'upgrade' else 'downgrade' end,
    format('Changed plan from %s to %s (%s)', v_old.name, v_new.name, p_billing_cycle)
  );
end;
$$;

create or replace function public.set_cancel_at_period_end(p_tenant_id uuid, p_cancel boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.has_permission(p_tenant_id, 'billing') then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;
  update public.subscriptions set cancel_at_period_end = p_cancel where tenant_id = p_tenant_id;
end;
$$;

-- Marks an invoice paid (admin, or the tenant's own "Pay now" until a
-- payment provider is wired in). Clears past-due once nothing is overdue.
create or replace function public.mark_invoice_paid(p_invoice_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_invoice public.invoices;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id;
  if not found then
    raise exception 'Invoice not found' using errcode = 'P0002';
  end if;
  if not public.has_permission(v_invoice.tenant_id, 'billing') then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;

  update public.invoices set status = 'paid', paid_at = public.local_today() where id = p_invoice_id;

  if not exists (
    select 1 from public.invoices
    where subscription_id = v_invoice.subscription_id and status = 'overdue'
  ) then
    update public.subscriptions set status = 'active'
    where id = v_invoice.subscription_id and status = 'past_due';
    update public.tenants set status = 'active'
    where id = v_invoice.tenant_id and status = 'past_due';
  end if;
  perform public.log_activity(v_invoice.tenant_id, 'payment', format('Paid invoice %s', v_invoice.number));
end;
$$;

-- ---------------------------------------------------------------------------
-- Platform admin: onboarding and status
-- ---------------------------------------------------------------------------
create or replace function public.slugify(p_text text)
returns text
language sql
immutable
set search_path = ''
as $$
  select trim(both '-' from regexp_replace(lower(coalesce(p_text, '')), '[^a-z0-9]+', '-', 'g'));
$$;

-- Creates a business with a 14-day trial and invites its owner (they get
-- access when they sign in with that email).
create or replace function public.create_tenant(
  p_name text,
  p_owner_name text,
  p_owner_email text,
  p_phone text default '',
  p_city text default '',
  p_plan_id text default 'starter',
  p_brand_primary text default '#1f5641'
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant_id uuid;
  v_slug text := public.slugify(p_name);
  v_today date := public.local_today();
  v_monogram text;
begin
  if not public.is_platform_admin() then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;
  if v_slug = '' then
    raise exception 'Enter the business name' using errcode = 'P0001';
  end if;
  if exists (select 1 from public.tenants where slug = v_slug) then
    raise exception 'A business with this name already exists' using errcode = 'P0001', hint = 'conflict';
  end if;

  select upper(string_agg(left(w, 1), ''))
    into v_monogram
  from (select w from regexp_split_to_table(btrim(p_name), '\s+') as w limit 2) words;

  insert into public.tenants (slug, name, legal_name, status, owner_name, owner_email, phone,
                              city, brand_primary, brand_monogram)
  values (v_slug, btrim(p_name), btrim(p_name), 'trialing', btrim(p_owner_name),
          lower(btrim(p_owner_email)), coalesce(p_phone, ''), coalesce(p_city, ''),
          p_brand_primary, left(coalesce(v_monogram, ''), 2))
  returning id into v_tenant_id;

  insert into public.booking_rules (tenant_id) values (v_tenant_id);

  insert into public.subscriptions (tenant_id, plan_id, status, billing_cycle, started_at,
                                    current_period_start, current_period_end, trial_ends_at)
  values (v_tenant_id, p_plan_id, 'trialing', 'monthly', v_today, v_today, v_today + 14, v_today + 14);

  insert into public.staff_members (tenant_id, name, email, phone, role)
  values (v_tenant_id, btrim(p_owner_name), lower(btrim(p_owner_email)), coalesce(p_phone, ''), 'owner');

  perform public.log_activity(v_tenant_id, 'signup', 'Created by platform admin — 14-day trial started');
  return v_tenant_id;
end;
$$;

create or replace function public.set_tenant_status(p_tenant_id uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.is_platform_admin() then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;
  if p_status not in ('active', 'trialing', 'past_due', 'suspended', 'cancelled') then
    raise exception 'Unknown status' using errcode = '22023';
  end if;
  update public.tenants set status = p_status where id = p_tenant_id;
  perform public.log_activity(
    p_tenant_id,
    case when p_status = 'suspended' then 'suspended' else 'support' end,
    case when p_status = 'suspended' then 'Suspended by platform admin' else format('Status set to %s', p_status) end
  );
end;
$$;

-- ===========================================================================
-- 20261101101000_analytics_functions.sql
-- ===========================================================================

-- Purpose: dashboard and report numbers, computed in the database (the
-- API returns at most 1,000 rows per request, so the app can't download
-- every booking to add them up). The JSON shapes match TenantAnalytics
-- and PlatformOverview in src/services/analyticsService.ts.

-- KPIs for one tenant over a date range (optionally one location).
create or replace function public.tenant_kpis(
  p_tenant_id uuid, p_from date, p_to date, p_location_id uuid default null
)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with b as (
    select * from public.bookings
    where tenant_id = p_tenant_id
      and business_date between p_from and p_to
      and (p_location_id is null or location_id = p_location_id)
  ),
  agg as (
    select
      coalesce(sum(amount_centavos) filter (where payment_status = 'paid'), 0) as revenue,
      count(*) filter (where status <> 'cancelled') as live,
      count(*) as total,
      count(*) filter (where status = 'cancelled') as cancelled,
      count(*) filter (where status = 'no_show') as no_shows,
      coalesce(sum(duration_hours) filter (where status <> 'cancelled'), 0) as hours,
      count(distinct customer_id) filter (where status <> 'cancelled') as customers
    from b
  ),
  cap as (
    select coalesce(sum((l.close_hour - l.open_hour) * (p_to - p_from + 1)), 0) as hours
    from public.courts c join public.locations l on l.id = c.location_id
    where c.tenant_id = p_tenant_id and c.status = 'active'
      and (p_location_id is null or c.location_id = p_location_id)
  )
  select jsonb_build_object(
    'revenue', agg.revenue,
    'bookings', agg.live,
    'bookedHours', agg.hours,
    'occupancy', case when cap.hours > 0 then agg.hours::numeric / cap.hours else 0 end,
    'averageBookingValue', case when agg.live > 0 then agg.revenue::numeric / agg.live else 0 end,
    'cancellationRate', case when agg.total > 0 then agg.cancelled::numeric / agg.total else 0 end,
    'noShowRate', case when agg.live > 0 then agg.no_shows::numeric / agg.live else 0 end,
    'uniqueCustomers', agg.customers
  )
  from agg, cap;
$$;

create or replace function public.tenant_analytics(
  p_tenant_id uuid, p_from date, p_to date, p_location_id uuid default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_span integer := p_to - p_from + 1;
  v_result jsonb;
begin
  if not public.has_permission(p_tenant_id, 'dashboard') then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;
  if v_span < 1 or v_span > 400 then
    raise exception 'Pick a range of 1 to 400 days.' using errcode = '22023';
  end if;

  with b as (
    select * from public.bookings
    where tenant_id = p_tenant_id
      and business_date between p_from and p_to
      and (p_location_id is null or location_id = p_location_id)
  ),
  locs as (
    select * from public.locations
    where tenant_id = p_tenant_id and (p_location_id is null or id = p_location_id)
  ),
  hours as (
    select gs.h % 24 as hour, count(*) as n
    from b cross join generate_series(b.start_hour, b.start_hour + b.duration_hours - 1) as gs (h)
    where b.status <> 'cancelled'
    group by 1
  )
  select jsonb_build_object(
    'current', public.tenant_kpis(p_tenant_id, p_from, p_to, p_location_id),
    'previous', public.tenant_kpis(p_tenant_id, p_from - v_span, p_from - 1, p_location_id),

    'daily', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'date', d::date,
        'revenue', coalesce((select sum(amount_centavos) from b
                             where b.business_date = d::date and b.payment_status = 'paid'), 0),
        'bookings', (select count(*) from b where b.business_date = d::date and b.status <> 'cancelled')
      ) order by d), '[]'::jsonb)
      from generate_series(p_from, p_to, interval '1 day') as d
    ),

    'byLocation', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'locationId', l.id,
        'name', l.name,
        'revenue', (public.tenant_kpis(p_tenant_id, p_from, p_to, l.id)->>'revenue')::numeric,
        'bookings', (public.tenant_kpis(p_tenant_id, p_from, p_to, l.id)->>'bookings')::numeric,
        'occupancy', (public.tenant_kpis(p_tenant_id, p_from, p_to, l.id)->>'occupancy')::numeric
      ) order by l.name), '[]'::jsonb)
      from locs l
    ),

    'byCourt', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'courtId', c.id,
        'name', c.name,
        'locationName', l.name,
        'occupancy', case when c.status = 'active' and l.close_hour > l.open_hour
          then coalesce((select sum(duration_hours) from b where b.court_id = c.id and b.status <> 'cancelled'), 0)::numeric
               / ((l.close_hour - l.open_hour) * v_span)
          else 0 end,
        'revenue', coalesce((select sum(amount_centavos) from b
                             where b.court_id = c.id and b.status <> 'cancelled'
                               and b.payment_status = 'paid'), 0)
      ) order by l.name, c.name), '[]'::jsonb)
      from public.courts c join locs l on l.id = c.location_id
    ),

    'byHour', (
      select coalesce(jsonb_agg(jsonb_build_object('hour', g.h, 'bookings', coalesce(hours.n, 0))
                                order by g.h), '[]'::jsonb)
      from generate_series(
        coalesce((select min(hour) from hours), 0),
        coalesce((select max(hour) from hours), -1)
      ) as g (h)
      left join hours on hours.hour = g.h
    ),

    'bySource', (
      select jsonb_agg(jsonb_build_object(
        'key', s.key,
        'value', (select count(*) from b where b.source = s.key and b.status <> 'cancelled')
      ) order by s.ord)
      from (values ('online', 1), ('walk_in', 2), ('phone', 3)) as s (key, ord)
    ),

    'byMethod', (
      select coalesce(jsonb_agg(jsonb_build_object('key', m.method, 'value', m.total)
                                order by m.total desc), '[]'::jsonb)
      from (
        select p.method, sum(p.amount_centavos) as total
        from public.payments p join b on b.id = p.booking_id
        where p.status = 'paid'
        group by p.method
      ) m
    ),

    'funnel', (
      select jsonb_build_object(
        'pageViews', coalesce(sum(page_views), 0),
        'bookingStarts', coalesce(sum(booking_starts), 0),
        'bookingsCompleted', coalesce(sum(bookings_completed), 0)
      )
      from public.page_view_stats
      where tenant_id = p_tenant_id
        and month in (date_trunc('month', p_from)::date, date_trunc('month', p_to)::date)
    )
  )
  into v_result;

  return v_result;
end;
$$;

-- ---------------------------------------------------------------------------
-- Platform overview (Super Admin)
-- ---------------------------------------------------------------------------
create or replace function public.subscription_mrr(p_plan public.plans, p_billing_cycle text)
returns integer
language sql
immutable
set search_path = ''
as $$
  select case when p_billing_cycle = 'annual'
              then round(p_plan.annual_price_centavos / 12.0)::integer
              else p_plan.monthly_price_centavos end;
$$;

create or replace function public.platform_overview()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_today date := public.local_today();
  v_from30 date := v_today - 29;
  v_from60 date := v_today - 59;
  v_this_week date := date_trunc('week', v_today)::date;
  v_result jsonb;
begin
  if not public.is_platform_admin() then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;

  with rows as (
    select
      t.id as tenant_id,
      case when s.status in ('active', 'past_due') then public.subscription_mrr(p, s.billing_cycle) else 0 end as mrr,
      (select count(*) from public.locations l where l.tenant_id = t.id) as locations,
      (select count(*) from public.courts c where c.tenant_id = t.id) as courts,
      (select count(*) from public.bookings b
        where b.tenant_id = t.id and b.business_date between v_from30 and v_today
          and b.status <> 'cancelled') as bookings30d,
      (select coalesce(sum(b.amount_centavos), 0) from public.bookings b
        where b.tenant_id = t.id and b.business_date between v_from30 and v_today
          and b.payment_status = 'paid') as gmv30d,
      public.compute_usage(t.id) as usage,
      p.id as plan_id
    from public.tenants t
    left join public.subscriptions s on s.tenant_id = t.id
    left join public.plans p on p.id = s.plan_id
  ),
  months as (
    select (date_trunc('month', v_today) - make_interval(months => 11 - i))::date as month
    from generate_series(0, 11) as i
  ),
  mrr_series as (
    select m.month, coalesce(sum(public.subscription_mrr(p, s.billing_cycle)), 0) as mrr
    from months m
    left join public.subscriptions s
      on date_trunc('month', s.started_at) <= m.month
     and s.status <> 'trialing'
     and not (s.status = 'cancelled' and m.month >= date_trunc('month', s.current_period_start))
    left join public.plans p on p.id = s.plan_id
    group by m.month
  ),
  weeks as (
    select v_this_week - (9 - i) * 7 as week_start from generate_series(0, 9) as i
  ),
  gmv_series as (
    select w.week_start,
           coalesce(sum(b.amount_centavos) filter (where b.payment_status = 'paid'), 0) as gmv,
           count(b.id) filter (where b.status <> 'cancelled') as bookings
    from weeks w
    left join public.bookings b
      on b.business_date >= w.week_start and b.business_date < w.week_start + 7
     and b.business_date <= v_today
    group by w.week_start
  )
  select jsonb_build_object(
    'mrr', (select coalesce(sum(mrr), 0) from rows),
    'previousMrr', coalesce((select mrr from mrr_series order by month desc offset 1 limit 1), 0),
    'tenants', jsonb_build_object(
      'total', (select count(*) from public.tenants),
      'active', (select count(*) from public.tenants where status = 'active'),
      'trialing', (select count(*) from public.tenants where status = 'trialing'),
      'pastDue', (select count(*) from public.tenants where status = 'past_due'),
      'suspended', (select count(*) from public.tenants where status in ('suspended', 'cancelled'))
    ),
    'gmv30d', (select coalesce(sum(amount_centavos), 0) from public.bookings
               where business_date between v_from30 and v_today and payment_status = 'paid'),
    'previousGmv30d', (select coalesce(sum(amount_centavos), 0) from public.bookings
                       where business_date between v_from60 and v_from30 - 1 and payment_status = 'paid'),
    'bookings30d', (select coalesce(sum(bookings30d), 0) from rows),
    'mrrSeries', (select jsonb_agg(jsonb_build_object('month', to_char(month, 'YYYY-MM'), 'mrr', mrr)
                                   order by month) from mrr_series),
    'gmvSeries', (select jsonb_agg(jsonb_build_object('weekStart', week_start, 'gmv', gmv, 'bookings', bookings)
                                   order by week_start) from gmv_series),
    'planMix', (
      select jsonb_agg(jsonb_build_object(
        'planId', p.id, 'name', p.name,
        'tenants', (select count(*) from rows r where r.plan_id = p.id),
        'mrr', (select coalesce(sum(r.mrr), 0) from rows r where r.plan_id = p.id)
      ) order by p.sort_order)
      from public.plans p
    ),
    'rows', (select jsonb_agg(jsonb_build_object(
      'tenantId', tenant_id, 'mrr', mrr, 'locations', locations, 'courts', courts,
      'bookings30d', bookings30d, 'gmv30d', gmv30d, 'usage', usage
    )) from rows)
  )
  into v_result;

  return v_result;
end;
$$;

-- ===========================================================================
-- 20261101101100_function_privileges.sql
-- ===========================================================================

-- Purpose: who may call which function through the API.
--
-- Postgres grants EXECUTE on new functions to PUBLIC by default, so
-- internal helpers (pricing, hold sweep, usage, activity log, trigger
-- functions) would otherwise be callable by anyone. Revoke everything,
-- then grant back exactly the public and staff entry points. Each staff
-- function still checks the caller's tenant permission itself.

revoke execute on all functions in schema public from public, anon, authenticated;
alter default privileges in schema public revoke execute on functions from public, anon, authenticated;

-- Used inside RLS policies and views, which run as the caller.
grant execute on function
  public.is_platform_admin(),
  public.staff_role(uuid),
  public.role_permissions(text),
  public.has_permission(uuid, text),
  public.is_tenant_member(uuid),
  public.phone_key(text),
  public.local_today(text)
to anon, authenticated;

-- Public booking site.
grant execute on function
  public.get_availability(uuid, date),
  public.create_booking_group(uuid, jsonb, text, text, text, integer, text, text, text, boolean),
  public.lookup_booking(uuid, text, text)
to anon, authenticated;

-- Signed-in staff and platform admins.
grant execute on function
  public.my_memberships(),
  public.tenant_usage(uuid),
  public.tenant_analytics(uuid, date, date, uuid),
  public.set_booking_status(uuid, text),
  public.cancel_booking(uuid, boolean),
  public.mark_booking_paid(uuid, text),
  public.reschedule_booking(uuid, uuid, date, integer, integer),
  public.review_payment(uuid, boolean),
  public.refund_payment(uuid),
  public.change_plan(uuid, text, text),
  public.set_cancel_at_period_end(uuid, boolean),
  public.mark_invoice_paid(uuid),
  public.create_tenant(text, text, text, text, text, text, text),
  public.set_tenant_status(uuid, text),
  public.platform_overview()
to authenticated;

-- ===========================================================================
-- 20261101101200_day_night_rates.sql
-- ===========================================================================

-- Purpose: simple day / night pricing per court.
--
-- Before: each court had a regular and a peak rate, and the business set
-- one "peak starts at" hour (+ which days) for all its courts.
-- After: each court has a day rate, a night rate and its own
-- night_start_hour. Night runs from that hour until closing — including
-- hours past midnight (24+ on the business day) — every day of the week.
--
-- Existing courts keep their prices: night_start_hour is copied from the
-- business's old peak_start_hour.

alter table public.courts rename column hourly_rate_centavos to day_rate_centavos;
alter table public.courts rename column peak_rate_centavos to night_rate_centavos;

alter table public.courts
  add column night_start_hour smallint not null default 17
    check (night_start_hour between 0 and 30);

comment on column public.courts.night_start_hour is
  'Hour of the business day (24h; 24+ = after midnight) when night_rate_centavos starts.';

update public.courts c
set night_start_hour = r.peak_start_hour
from public.booking_rules r
where r.tenant_id = c.tenant_id;

-- Price of a booking in centavos: each hour is day or night on its own (a
-- booking can start in the day and run into the night). Mirrors
-- src/utils/pricing.ts.
create or replace function public.booking_price(
  p_court_id uuid, p_date date, p_start_hour integer, p_duration_hours integer
)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(sum(
    case when h >= c.night_start_hour then c.night_rate_centavos else c.day_rate_centavos end
  ), 0)::integer
  from public.courts c
  cross join generate_series(p_start_hour, p_start_hour + p_duration_hours - 1) as h
  where c.id = p_court_id;
$$;

-- The business-wide peak setting is replaced by the per-court night start.
alter table public.booking_rules drop column peak_start_hour;
alter table public.booking_rules drop column peak_days;

update public.plans
set features = array_replace(features, 'Peak & off-peak pricing', 'Day & night rates')
where 'Peak & off-peak pricing' = any (features);

-- ===========================================================================
-- 20261101101300_payment_accounts.sql
-- ===========================================================================

-- Purpose: where customers send money — each business's GCash / Maya /
-- bank details and QR code images, shown on the booking site's payment
-- step (match-pickleball's venue payment details + payment-qr bucket,
-- made per tenant).
--
-- Card payments are deliberately not here: they need a payment provider
-- (e.g. PayMongo) and Sideline never stores card details.

create table public.payment_accounts (
  tenant_id uuid not null references public.tenants (id) on delete cascade,
  method text not null check (method in ('gcash', 'maya', 'bank_transfer')),
  account_name text not null default '' check (char_length(account_name) <= 100),
  account_number text not null default '' check (char_length(account_number) <= 50),
  -- Bank transfers only, e.g. "BDO", "GoTyme".
  bank_name text not null default '' check (char_length(bank_name) <= 60),
  instructions text not null default '' check (char_length(instructions) <= 300),
  -- Object path in the public payment-qr bucket ("<tenant_id>/<file>"), or NULL.
  qr_path text check (qr_path is null or char_length(qr_path) <= 200),
  updated_at timestamptz not null default now(),
  primary key (tenant_id, method),
  constraint payment_accounts_qr_in_own_folder
    check (qr_path is null or qr_path like tenant_id::text || '/%')
);

comment on table public.payment_accounts is
  'Payment details customers need to pay a business (public). Writable by '
  'staff with the settings permission.';

create trigger set_payment_accounts_updated_at
  before update on public.payment_accounts
  for each row execute function public.set_updated_at();

alter table public.payment_accounts enable row level security;

create policy payment_accounts_select on public.payment_accounts
  for select to anon, authenticated using (true);
create policy payment_accounts_insert on public.payment_accounts
  for insert to authenticated with check (public.has_permission(tenant_id, 'settings'));
create policy payment_accounts_update on public.payment_accounts
  for update to authenticated
  using (public.has_permission(tenant_id, 'settings'))
  with check (public.has_permission(tenant_id, 'settings'));
create policy payment_accounts_delete on public.payment_accounts
  for delete to authenticated using (public.has_permission(tenant_id, 'settings'));

grant select on public.payment_accounts to anon, authenticated;
grant insert, update, delete on public.payment_accounts to authenticated;

-- ---------------------------------------------------------------------------
-- QR images: public bucket (they're meant to be shown to every customer),
-- one folder per tenant; only that tenant's staff with the settings
-- permission may write into it.
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('payment-qr', 'payment-qr', true, 2097152, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

-- The tenant a payment-qr object belongs to (its first folder), or NULL
-- for a malformed path. CASE keeps the uuid cast from ever erroring.
create or replace function public.payment_qr_tenant(p_name text)
returns uuid
language sql
immutable
set search_path = ''
as $$
  select case
    when split_part(p_name, '/', 1) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    then split_part(p_name, '/', 1)::uuid
  end;
$$;

grant execute on function public.payment_qr_tenant(text) to anon, authenticated;

create policy payment_qr_select on storage.objects
  for select to anon, authenticated
  using (bucket_id = 'payment-qr');

create policy payment_qr_insert on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'payment-qr'
    and coalesce(public.has_permission(public.payment_qr_tenant(name), 'settings'), false)
  );

create policy payment_qr_update on storage.objects
  for update to authenticated
  using (
    bucket_id = 'payment-qr'
    and coalesce(public.has_permission(public.payment_qr_tenant(name), 'settings'), false)
  )
  with check (
    bucket_id = 'payment-qr'
    and coalesce(public.has_permission(public.payment_qr_tenant(name), 'settings'), false)
  );

create policy payment_qr_delete on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'payment-qr'
    and coalesce(public.has_permission(public.payment_qr_tenant(name), 'settings'), false)
  );

-- ===========================================================================
-- 20261101101400_payment_proofs.sql
-- ===========================================================================

-- Purpose: customers upload proof of payment (GCash / Maya / bank transfer
-- screenshot) and staff view it when approving — match-pickleball's
-- payment-proofs flow, made per tenant.
--
-- Flow: the booking site uploads the file into the private payment-proofs
-- bucket under "<tenant_id>/<random>", creates the booking, then calls
-- attach_payment_proof() with the booking reference + phone number. Only
-- that business's staff with the payments permission can read the files
-- (signed URLs); customers can upload but never list or view.

alter table public.payments
  add column proof_path text check (proof_path is null or char_length(proof_path) <= 200),
  add column transaction_reference text not null default ''
    check (char_length(transaction_reference) <= 100),
  add constraint payments_proof_in_own_folder
    check (proof_path is null or proof_path like tenant_id::text || '/%');

comment on column public.payments.proof_path is
  'Object path of the customer''s payment screenshot in the private payment-proofs bucket.';

-- payment_rows lists p.*, which was expanded when the view was created;
-- recreate it so it includes the new columns.
drop view public.payment_rows;
create view public.payment_rows
with (security_invoker = true) as
select
  p.*,
  b.reference as booking_reference,
  b.business_date as booking_date,
  b.location_id,
  c.name as customer_name
from public.payments p
join public.bookings b on b.id = p.booking_id
join public.customers c on c.id = p.customer_id;

grant select on public.payment_rows to authenticated;

-- ---------------------------------------------------------------------------
-- Private bucket: anyone may upload into an existing business's folder;
-- only that business's payments staff may read.
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('payment-proofs', 'payment-proofs', false, 5242880,
        array['image/jpeg', 'image/png', 'image/webp', 'application/pdf'])
on conflict (id) do nothing;

-- Same "<tenant_id>/…" folder convention as payment-qr.
create or replace function public.storage_tenant(p_name text)
returns uuid
language sql
immutable
set search_path = ''
as $$
  select public.payment_qr_tenant(p_name);
$$;

create or replace function public.tenant_exists(p_tenant_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.tenants where id = p_tenant_id and status not in ('suspended', 'cancelled'));
$$;

grant execute on function public.storage_tenant(text), public.tenant_exists(uuid) to anon, authenticated;

create policy payment_proofs_insert on storage.objects
  for insert to anon, authenticated
  with check (
    bucket_id = 'payment-proofs'
    and coalesce(public.tenant_exists(public.storage_tenant(name)), false)
  );

create policy payment_proofs_select on storage.objects
  for select to authenticated
  using (
    bucket_id = 'payment-proofs'
    and coalesce(public.has_permission(public.storage_tenant(name), 'payments'), false)
  );

-- ---------------------------------------------------------------------------
-- attach_payment_proof(): links an uploaded screenshot to the pending
-- payment(s) of a booking. Needs the booking reference AND the phone
-- number used (same check as lookup_booking), and the file must exist in
-- that business's folder. Covers every date of a multi-date booking.
-- ---------------------------------------------------------------------------
create or replace function public.attach_payment_proof(
  p_tenant_id uuid,
  p_reference text,
  p_phone text,
  p_proof_path text,
  p_transaction_reference text default ''
)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_count integer;
begin
  if char_length(coalesce(p_transaction_reference, '')) > 100 then
    raise exception 'The reference number is too long.' using errcode = 'P0001';
  end if;
  if public.storage_tenant(p_proof_path) is distinct from p_tenant_id
     or not exists (
       select 1 from storage.objects where bucket_id = 'payment-proofs' and name = p_proof_path
     ) then
    raise exception 'Upload your payment screenshot first.' using errcode = 'P0001';
  end if;

  update public.payments p
  set proof_path = p_proof_path,
      transaction_reference = coalesce(btrim(p_transaction_reference), '')
  from public.bookings b
  join public.customers c on c.id = b.customer_id
  where p.booking_id = b.id
    and p.status = 'pending'
    and b.tenant_id = p_tenant_id
    and b.reference = upper(btrim(p_reference))
    and char_length(public.phone_key(p_phone)) = 10
    and public.phone_key(c.phone) = public.phone_key(p_phone);
  get diagnostics v_count = row_count;

  if v_count = 0 then
    raise exception 'No payment waiting for proof on that booking.' using errcode = 'P0002';
  end if;
  return v_count;
end;
$$;

revoke execute on function public.attach_payment_proof(uuid, text, text, text, text) from public;
grant execute on function public.attach_payment_proof(uuid, text, text, text, text) to anon, authenticated;

-- ===========================================================================
-- 20261101101500_branding_hero.sql
-- ===========================================================================

-- Purpose: booking-site homepage banner style per business — the plain
-- brand color (as before) or a photo carousel of up to 3 images, chosen
-- under Settings → Branding.
--
-- Photos live in the public `branding` Storage bucket (they're shown to
-- every visitor), one folder per business ("<tenant_id>/…"); only that
-- business's staff with the settings permission may upload or delete.
-- tenants.hero_images stores object paths, not URLs.

-- True when every path is inside the business's own folder.
create or replace function public.paths_in_folder(p_paths text[], p_tenant_id uuid)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select coalesce(bool_and(p like p_tenant_id::text || '/%'), true)
  from unnest(p_paths) as p;
$$;

alter table public.tenants
  add column hero_style text not null default 'color' check (hero_style in ('color', 'carousel')),
  add column hero_images text[] not null default '{}',
  add constraint tenants_hero_images_max check (cardinality(hero_images) <= 3),
  add constraint tenants_hero_images_in_own_folder check (public.paths_in_folder(hero_images, id));

comment on column public.tenants.hero_style is
  'Booking-site homepage banner: color (brand color) or carousel (hero_images).';
comment on column public.tenants.hero_images is
  'Up to 3 object paths in the public branding bucket, in display order.';

-- The branding columns are owner-editable like the rest of the brand.
grant update (hero_style, hero_images) on public.tenants to authenticated;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('branding', 'branding', true, 5242880, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

create policy branding_select on storage.objects
  for select to anon, authenticated
  using (bucket_id = 'branding');

create policy branding_insert on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'branding'
    and coalesce(public.has_permission(public.storage_tenant(name), 'settings'), false)
  );

create policy branding_delete on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'branding'
    and coalesce(public.has_permission(public.storage_tenant(name), 'settings'), false)
  );

-- ===========================================================================
-- 20261101101600_tenant_policies.sql
-- ===========================================================================

-- Purpose: each business's own rules & policies (house rules, cancellations
-- and refunds, dress code…), written under Settings → Policies and shown on
-- its booking site and at checkout.
--
-- Stored as an ordered list of sections on the tenant:
--   [{"title": "House rules", "body": "- Non-marking shoes only\n- …"}, …]
-- Bodies are plain text (blank line = new paragraph, "- " = bullet); the
-- booking site never renders them as HTML.

-- True when p is a list of at most 10 sections, each with a 1–80 character
-- title and a body of at most 4000 characters (and no other keys).
create or replace function public.valid_policies(p jsonb)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select jsonb_typeof(p) = 'array'
    and jsonb_array_length(p) <= 10
    and coalesce((
      select bool_and(
        jsonb_typeof(s) = 'object'
        and jsonb_typeof(s -> 'title') = 'string'
        and jsonb_typeof(s -> 'body') = 'string'
        and char_length(btrim(s ->> 'title')) between 1 and 80
        and char_length(s ->> 'body') <= 4000
        and (select count(*) from jsonb_object_keys(s)) = 2
      )
      from jsonb_array_elements(p) as s
    ), true);
$$;

alter table public.tenants
  add column policies jsonb not null default '[]'::jsonb,
  add constraint tenants_policies_valid check (public.valid_policies(policies));

comment on column public.tenants.policies is
  'Rules & policies shown on the booking site: ordered [{title, body}], max 10.';

-- Owner-editable like the rest of the business profile (tenants_update RLS
-- already limits updates to the business's settings staff).
grant update (policies) on public.tenants to authenticated;

-- ===========================================================================
-- 20261101101700_business_accounts.sql
-- ===========================================================================

-- Purpose: one kind of business account instead of staff roles.
--
-- Every login attached to a business (a staff_members row) now has full
-- access to it: bookings, payments, settings, billing. Businesses can no
-- longer add people themselves; only a platform admin adds, disables or
-- removes accounts (Super Admin → business → Business accounts).
--
-- Existing non-owner rows (manager, front desk, coach) are kept but
-- disabled, so nobody gains access by this change; an admin can switch any
-- of them back on. Staff-seat plan limits go away.

-- 1. Collapse roles. Runs as the SQL Editor's postgres role, which the
--    guard_staff_owner trigger lets through.
update public.staff_members
set status = 'disabled', role = 'owner'
where role <> 'owner';

alter table public.staff_members
  drop constraint if exists staff_members_role_check,
  alter column role set default 'owner',
  add constraint staff_members_role_check check (role = 'owner');

-- Mirrors rolePermissions in src/utils/permissions.ts.
create or replace function public.role_permissions(p_role text)
returns text[]
language sql
immutable
set search_path = ''
as $$
  select case p_role
    when 'owner' then array['dashboard', 'calendar', 'bookings', 'customers', 'payments',
                            'venues', 'reports', 'settings', 'billing']
    else array[]::text[]
  end;
$$;

-- 2. Only platform admins manage accounts. Members can still see who else
--    has access to their business (staff_select is unchanged).
drop policy if exists staff_insert on public.staff_members;
drop policy if exists staff_update on public.staff_members;
drop policy if exists staff_delete on public.staff_members;

create policy staff_insert on public.staff_members
  for insert to authenticated with check (public.is_platform_admin());
create policy staff_update on public.staff_members
  for update to authenticated
  using (public.is_platform_admin()) with check (public.is_platform_admin());
create policy staff_delete on public.staff_members
  for delete to authenticated using (public.is_platform_admin());

-- 3. No staff-seat limits: accounts are added by Sideline, not counted
--    against the plan.
update public.plans
set limit_staff = null,
    features = array_remove(features, 'Staff roles'),
    description = replace(description, 'adding courts, staff and a second site',
                          'adding courts and a second site');

create or replace function public.compute_usage(p_tenant_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with p as (
    select pl.*
    from public.subscriptions s join public.plans pl on pl.id = s.plan_id
    where s.tenant_id = p_tenant_id
  ), tz as (
    select timezone from public.tenants where id = p_tenant_id
  )
  select jsonb_build_array(
    jsonb_build_object('key', 'locations',
      'used', (select count(*) from public.locations where tenant_id = p_tenant_id),
      'limit', (select limit_locations from p)),
    jsonb_build_object('key', 'courts',
      'used', (select count(*) from public.courts where tenant_id = p_tenant_id),
      'limit', (select limit_courts from p)),
    jsonb_build_object('key', 'bookingsPerMonth',
      'used', (select count(*) from public.bookings
               where tenant_id = p_tenant_id and status <> 'cancelled'
                 and date_trunc('month', business_date)
                     = date_trunc('month', public.local_today((select timezone from tz)))),
      'limit', (select limit_bookings_per_month from p))
  );
$$;

-- ===========================================================================
-- 20261101101800_plan_requests.sql
-- ===========================================================================

-- Purpose: plan changes need Sideline's OK while there is no automatic
-- payment. A business sends a plan change request (Subscription page); a
-- platform admin collects payment however they normally do, then approves
-- (the plan switches that day) or declines with a reason. Only platform
-- admins can change a plan directly.

create table public.plan_requests (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants (id) on delete cascade,
  -- Plan at the time of the request, for the admin's "from → to" view.
  from_plan_id text not null references public.plans (id),
  from_billing_cycle text not null check (from_billing_cycle in ('monthly', 'annual')),
  plan_id text not null references public.plans (id),
  billing_cycle text not null check (billing_cycle in ('monthly', 'annual')),
  note text not null default '' check (char_length(note) <= 500),
  status text not null default 'pending'
    check (status in ('pending', 'approved', 'declined', 'cancelled')),
  decision_note text not null default '' check (char_length(decision_note) <= 500),
  requested_by uuid references auth.users (id) on delete set null,
  decided_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  decided_at timestamptz
);

-- One open request per business at a time.
create unique index plan_requests_one_pending on public.plan_requests (tenant_id)
  where status = 'pending';
create index plan_requests_tenant_idx on public.plan_requests (tenant_id, created_at desc);

alter table public.plan_requests enable row level security;

-- Read-only through the API; changes go through the functions below.
create policy plan_requests_select on public.plan_requests
  for select to authenticated using (public.has_permission(tenant_id, 'billing'));
grant select on public.plan_requests to authenticated;

-- Direct plan changes: platform admins only (also used by approvals).
create or replace function public.change_plan(p_tenant_id uuid, p_plan_id text, p_billing_cycle text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_sub public.subscriptions;
  v_old public.plans;
  v_new public.plans;
  v_usage jsonb := public.compute_usage(p_tenant_id);
  v_item jsonb;
  v_limit integer;
  v_today date := public.local_today();
begin
  if not public.is_platform_admin() then
    raise exception 'Plan changes are confirmed by Sideline. Send a plan change request instead.'
      using errcode = '42501';
  end if;
  if p_billing_cycle not in ('monthly', 'annual') then
    raise exception 'Unknown billing cycle' using errcode = '22023';
  end if;
  select * into v_sub from public.subscriptions where tenant_id = p_tenant_id for update;
  if not found then
    raise exception 'No subscription for this business' using errcode = 'P0002';
  end if;
  select * into v_old from public.plans where id = v_sub.plan_id;
  select * into v_new from public.plans where id = p_plan_id;
  if not found then
    raise exception 'Plan not found' using errcode = 'P0002';
  end if;

  for v_item in select * from jsonb_array_elements(v_usage) loop
    continue when v_item->>'key' = 'bookingsPerMonth';
    v_limit := case v_item->>'key'
      when 'locations' then v_new.limit_locations
      when 'courts' then v_new.limit_courts
    end;
    if v_limit is not null and (v_item->>'used')::integer > v_limit then
      raise exception 'Can''t switch: you''re using % % and the % plan allows %.',
        v_item->>'used', v_item->>'key', v_new.name, v_limit using errcode = 'P0001';
    end if;
  end loop;

  update public.subscriptions
  set plan_id = p_plan_id,
      billing_cycle = p_billing_cycle,
      cancel_at_period_end = false,
      status = case when status = 'trialing' then status else 'active' end,
      current_period_start = case when status = 'trialing' then current_period_start else v_today end,
      current_period_end = case
        when status = 'trialing' then current_period_end
        when p_billing_cycle = 'annual' then (v_today + interval '1 year')::date
        else (v_today + interval '1 month')::date
      end
  where id = v_sub.id;

  perform public.log_activity(
    p_tenant_id,
    case when v_new.monthly_price_centavos >= v_old.monthly_price_centavos then 'upgrade' else 'downgrade' end,
    format('Changed plan from %s to %s (%s)', v_old.name, v_new.name, p_billing_cycle)
  );
end;
$$;

-- A business asks to switch plan / billing cycle. Plans below current usage
-- and non-public plans (Enterprise) are refused up front.
create or replace function public.request_plan_change(
  p_tenant_id uuid, p_plan_id text, p_billing_cycle text, p_note text default ''
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_sub public.subscriptions;
  v_new public.plans;
  v_item jsonb;
  v_limit integer;
  v_id uuid;
begin
  if not public.has_permission(p_tenant_id, 'billing') then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;
  if p_billing_cycle not in ('monthly', 'annual') then
    raise exception 'Unknown billing cycle' using errcode = '22023';
  end if;
  select * into v_sub from public.subscriptions where tenant_id = p_tenant_id;
  if not found then
    raise exception 'No subscription for this business' using errcode = 'P0002';
  end if;
  select * into v_new from public.plans where id = p_plan_id;
  if not found then
    raise exception 'Plan not found' using errcode = 'P0002';
  end if;
  if not v_new.is_public then
    raise exception 'Contact Sideline to switch to the % plan.', v_new.name using errcode = 'P0001';
  end if;
  if v_sub.plan_id = p_plan_id and v_sub.billing_cycle = p_billing_cycle
     and v_sub.status <> 'trialing' then
    raise exception 'You''re already on this plan.' using errcode = 'P0001';
  end if;
  for v_item in select * from jsonb_array_elements(public.compute_usage(p_tenant_id)) loop
    continue when v_item->>'key' = 'bookingsPerMonth';
    v_limit := case v_item->>'key'
      when 'locations' then v_new.limit_locations
      when 'courts' then v_new.limit_courts
    end;
    if v_limit is not null and (v_item->>'used')::integer > v_limit then
      raise exception 'Can''t switch: you''re using % % and the % plan allows %.',
        v_item->>'used', v_item->>'key', v_new.name, v_limit using errcode = 'P0001';
    end if;
  end loop;
  if exists (select 1 from public.plan_requests
             where tenant_id = p_tenant_id and status = 'pending') then
    raise exception 'You already have a plan change request waiting. Cancel it first to send a new one.'
      using errcode = 'P0001', hint = 'conflict';
  end if;

  insert into public.plan_requests (tenant_id, from_plan_id, from_billing_cycle, plan_id,
                                    billing_cycle, note, requested_by)
  values (p_tenant_id, v_sub.plan_id, v_sub.billing_cycle, p_plan_id, p_billing_cycle,
          left(btrim(coalesce(p_note, '')), 500), (select auth.uid()))
  returning id into v_id;

  perform public.log_activity(p_tenant_id, 'support',
    format('Requested a plan change to %s (%s)', v_new.name, p_billing_cycle));
  return v_id;
end;
$$;

-- The business withdraws its own pending request.
create or replace function public.cancel_plan_request(p_request_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_req public.plan_requests;
begin
  select * into v_req from public.plan_requests where id = p_request_id for update;
  if not found or not public.has_permission(v_req.tenant_id, 'billing') then
    raise exception 'Request not found' using errcode = 'P0002';
  end if;
  if v_req.status <> 'pending' then
    raise exception 'This request was already handled.' using errcode = 'P0001';
  end if;
  update public.plan_requests
  set status = 'cancelled', decided_at = now(), decided_by = (select auth.uid())
  where id = p_request_id;
end;
$$;

-- Platform admin approves (switches the plan now) or declines with a reason.
create or replace function public.decide_plan_request(
  p_request_id uuid, p_approve boolean, p_note text default ''
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_req public.plan_requests;
begin
  if not public.is_platform_admin() then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;
  select * into v_req from public.plan_requests where id = p_request_id for update;
  if not found then
    raise exception 'Request not found' using errcode = 'P0002';
  end if;
  if v_req.status <> 'pending' then
    raise exception 'This request was already handled.' using errcode = 'P0001';
  end if;
  if p_approve then
    perform public.change_plan(v_req.tenant_id, v_req.plan_id, v_req.billing_cycle);
  end if;
  update public.plan_requests
  set status = case when p_approve then 'approved' else 'declined' end,
      decision_note = left(btrim(coalesce(p_note, '')), 500),
      decided_by = (select auth.uid()),
      decided_at = now()
  where id = p_request_id;
end;
$$;

grant execute on function
  public.request_plan_change(uuid, text, text, text),
  public.cancel_plan_request(uuid),
  public.decide_plan_request(uuid, boolean, text)
to authenticated;

-- ===========================================================================
-- 20261101101900_abuse_protection.sql
-- ===========================================================================

-- Purpose: limits on the public booking site, enforced in the database
-- (the app's publishable key is public, so browser-only checks can be
-- skipped by calling the API directly).
--
--   * Booking: one phone number can hold at most 3 unpaid upcoming online
--     bookings per business, and one network (IP) can make at most 15
--     online bookings per business per hour.
--   * "Find my booking": at most 30 lookups per network per 10 minutes and
--     10 per booking reference per hour (stops guessing phone numbers).
--   * Payment proofs: uploads only into a folder named after a real booking
--     made in the last 2 hours that isn't paid yet, at most 3 files each;
--     attaching is limited like lookups.
--
-- Staff and platform admins are never limited. Requests without an IP
-- (SQL Editor, tests) skip the per-network limits only.

-- ---------------------------------------------------------------------------
-- Rate-limit counters (private: no API access)
-- ---------------------------------------------------------------------------
create table public.rate_limit_hits (
  bucket text not null,
  -- sha256 of the limited key (IP, reference…), never the raw value.
  key_hash text not null,
  hit_at timestamptz not null default now()
);
create index rate_limit_hits_lookup on public.rate_limit_hits (bucket, key_hash, hit_at);
alter table public.rate_limit_hits enable row level security;

-- The caller's IP as seen by Supabase's API gateway, or null.
create or replace function public.client_ip()
returns text
language plpgsql
stable
set search_path = ''
as $$
declare
  v_headers json;
begin
  begin
    v_headers := nullif(current_setting('request.headers', true), '')::json;
  exception when others then
    return null;
  end;
  if v_headers is null then
    return null;
  end if;
  return nullif(btrim(coalesce(
    v_headers->>'cf-connecting-ip',
    v_headers->>'x-real-ip',
    split_part(v_headers->>'x-forwarded-for', ',', 1)
  )), '');
end;
$$;

-- Records one hit for (bucket, key); raises once `p_max` hits fall inside
-- `p_window`. A null key (no IP) is never limited.
create or replace function public.hit_rate_limit(
  p_bucket text, p_key text, p_max integer, p_window interval
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_hash text;
begin
  if p_key is null or p_key = '' then
    return;
  end if;
  v_hash := encode(sha256(convert_to(p_bucket || ':' || p_key, 'UTF8')), 'hex');
  -- Housekeeping: nothing is limited over more than a day.
  delete from public.rate_limit_hits where hit_at < now() - interval '1 day';
  if (select count(*) from public.rate_limit_hits
      where bucket = p_bucket and key_hash = v_hash and hit_at > now() - p_window) >= p_max then
    raise exception 'Too many attempts. Please wait a few minutes and try again.'
      using errcode = 'P0001', hint = 'rate_limited';
  end if;
  insert into public.rate_limit_hits (bucket, key_hash) values (p_bucket, v_hash);
end;
$$;

-- ---------------------------------------------------------------------------
-- Booking
-- ---------------------------------------------------------------------------
alter function public.create_booking_group(uuid, jsonb, text, text, text, integer, text, text, text, boolean)
  rename to create_booking_group_core;
revoke execute on function
  public.create_booking_group_core(uuid, jsonb, text, text, text, integer, text, text, text, boolean)
  from public, anon, authenticated;

create or replace function public.create_booking_group(
  p_tenant_id uuid,
  p_slots jsonb,
  p_customer_name text,
  p_customer_phone text,
  p_customer_email text default '',
  p_players integer default 4,
  p_notes text default '',
  p_source text default 'online',
  p_payment_method text default null,
  p_payment_pending boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_open integer;
begin
  if p_source = 'online' and not public.has_permission(p_tenant_id, 'bookings') then
    perform public.expire_stale_holds();
    -- Unpaid upcoming online bookings (counted per reference) for this phone.
    select count(distinct b.reference) into v_open
    from public.bookings b
    join public.customers c on c.id = b.customer_id
    where b.tenant_id = p_tenant_id
      and b.source = 'online'
      and b.status in ('pending', 'confirmed')
      and b.payment_status = 'unpaid'
      and b.business_date >= public.local_today()
      and char_length(public.phone_key(p_customer_phone)) = 10
      and public.phone_key(c.phone) = public.phone_key(p_customer_phone);
    if v_open >= 3 then
      raise exception 'This number already has 3 unpaid bookings here. Pay for or cancel one first, or contact the venue.'
        using errcode = 'P0001', hint = 'rate_limited';
    end if;
    perform public.hit_rate_limit('booking', p_tenant_id::text || '|' || public.client_ip(),
                                  15, interval '1 hour');
  end if;
  return public.create_booking_group_core(p_tenant_id, p_slots, p_customer_name, p_customer_phone,
    p_customer_email, p_players, p_notes, p_source, p_payment_method, p_payment_pending);
end;
$$;

-- ---------------------------------------------------------------------------
-- Find my booking
-- ---------------------------------------------------------------------------
alter function public.lookup_booking(uuid, text, text) rename to lookup_booking_core;
revoke execute on function public.lookup_booking_core(uuid, text, text)
  from public, anon, authenticated;

create or replace function public.lookup_booking(p_tenant_id uuid, p_reference text, p_phone text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.hit_rate_limit('lookup:ip', public.client_ip(), 30, interval '10 minutes');
  perform public.hit_rate_limit('lookup:ref',
    p_tenant_id::text || '|' || upper(btrim(coalesce(p_reference, ''))), 10, interval '1 hour');
  return public.lookup_booking_core(p_tenant_id, p_reference, p_phone);
end;
$$;

-- ---------------------------------------------------------------------------
-- Payment proofs
-- ---------------------------------------------------------------------------
alter function public.attach_payment_proof(uuid, text, text, text, text)
  rename to attach_payment_proof_core;
revoke execute on function public.attach_payment_proof_core(uuid, text, text, text, text)
  from public, anon, authenticated;

create or replace function public.attach_payment_proof(
  p_tenant_id uuid,
  p_reference text,
  p_phone text,
  p_proof_path text,
  p_transaction_reference text default ''
)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.has_permission(p_tenant_id, 'payments') then
    perform public.hit_rate_limit('proof:ip', public.client_ip(), 20, interval '1 hour');
    perform public.hit_rate_limit('proof:ref',
      p_tenant_id::text || '|' || upper(btrim(coalesce(p_reference, ''))), 5, interval '1 hour');
  end if;
  return public.attach_payment_proof_core(p_tenant_id, p_reference, p_phone, p_proof_path,
    p_transaction_reference);
end;
$$;

-- Uploads go to "<tenant_id>/<booking reference>/<random>.<ext>". Allowed
-- only for a booking of that business made in the last 2 hours that is
-- still unpaid, and at most 3 files per booking.
create or replace function public.proof_upload_allowed(p_name text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
      select 1 from public.bookings b
      where b.tenant_id = public.storage_tenant(p_name)
        and b.reference = upper(split_part(p_name, '/', 2))
        and b.payment_status = 'unpaid'
        and b.status in ('pending', 'confirmed')
        and b.created_at > now() - interval '2 hours'
    )
    and (select count(*) from storage.objects o
         where o.bucket_id = 'payment-proofs'
           and o.name like split_part(p_name, '/', 1) || '/' || split_part(p_name, '/', 2) || '/%') < 3;
$$;

drop policy if exists payment_proofs_insert on storage.objects;
create policy payment_proofs_insert on storage.objects
  for insert to anon, authenticated
  with check (
    bucket_id = 'payment-proofs'
    and coalesce(public.proof_upload_allowed(name), false)
  );

grant execute on function
  public.create_booking_group(uuid, jsonb, text, text, text, integer, text, text, text, boolean),
  public.lookup_booking(uuid, text, text),
  public.attach_payment_proof(uuid, text, text, text, text),
  public.proof_upload_allowed(text)
to anon, authenticated;

-- ===========================================================================
-- 20261101102000_invoice_payments.sql
-- ===========================================================================

-- Purpose: businesses pay their Sideline invoices manually, like players
-- pay businesses. Sideline publishes its own GCash / Maya / bank details
-- (platform_payment_accounts); the business pays, uploads proof on the
-- invoice, and a platform admin approves (invoice paid) or declines with
-- a reason. Businesses can no longer mark their own invoices paid.

-- ---------------------------------------------------------------------------
-- Where businesses send money to Sideline
-- ---------------------------------------------------------------------------
create table public.platform_payment_accounts (
  method text primary key check (method in ('gcash', 'maya', 'bank_transfer')),
  account_name text not null default '' check (char_length(account_name) <= 100),
  account_number text not null default '' check (char_length(account_number) <= 50),
  bank_name text not null default '' check (char_length(bank_name) <= 60),
  instructions text not null default '' check (char_length(instructions) <= 300),
  -- Object path in the public payment-qr bucket ("sideline/<file>"), or NULL.
  qr_path text check (qr_path is null or qr_path like 'sideline/%'),
  updated_at timestamptz not null default now()
);

comment on table public.platform_payment_accounts is
  'Sideline''s own payment details, shown to businesses paying an invoice. '
  'Writable by platform admins only.';

create trigger set_platform_payment_accounts_updated_at
  before update on public.platform_payment_accounts
  for each row execute function public.set_updated_at();

alter table public.platform_payment_accounts enable row level security;

create policy platform_payment_accounts_select on public.platform_payment_accounts
  for select to authenticated using (true);
create policy platform_payment_accounts_insert on public.platform_payment_accounts
  for insert to authenticated with check (public.is_platform_admin());
create policy platform_payment_accounts_update on public.platform_payment_accounts
  for update to authenticated
  using (public.is_platform_admin()) with check (public.is_platform_admin());
create policy platform_payment_accounts_delete on public.platform_payment_accounts
  for delete to authenticated using (public.is_platform_admin());

grant select, insert, update, delete on public.platform_payment_accounts to authenticated;

-- Sideline's QR images live in the public payment-qr bucket's "sideline/" folder.
create policy payment_qr_platform_insert on storage.objects
  for insert to authenticated
  with check (bucket_id = 'payment-qr' and name like 'sideline/%' and public.is_platform_admin());
create policy payment_qr_platform_update on storage.objects
  for update to authenticated
  using (bucket_id = 'payment-qr' and name like 'sideline/%' and public.is_platform_admin())
  with check (bucket_id = 'payment-qr' and name like 'sideline/%' and public.is_platform_admin());
create policy payment_qr_platform_delete on storage.objects
  for delete to authenticated
  using (bucket_id = 'payment-qr' and name like 'sideline/%' and public.is_platform_admin());

-- ---------------------------------------------------------------------------
-- Proof of payment on invoices
-- ---------------------------------------------------------------------------
alter table public.invoices
  add column payment_method text check (payment_method in ('gcash', 'maya', 'bank_transfer')),
  add column proof_path text check (proof_path is null or char_length(proof_path) <= 200),
  add column transaction_reference text not null default ''
    check (char_length(transaction_reference) <= 100),
  -- Set while a proof waits for review; cleared when it's declined.
  add column proof_submitted_at timestamptz,
  -- Sideline's reason when a proof is declined.
  add column review_note text not null default '' check (char_length(review_note) <= 500),
  add constraint invoices_proof_in_own_folder
    check (proof_path is null or proof_path like tenant_id::text || '/' || id::text || '/%');

comment on column public.invoices.proof_submitted_at is
  'When the business sent proof of payment; NULL when nothing is waiting for review.';

-- Private bucket, one folder per invoice: "<tenant_id>/<invoice_id>/<file>".
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('invoice-proofs', 'invoice-proofs', false, 5242880,
        array['image/jpeg', 'image/png', 'image/webp', 'application/pdf'])
on conflict (id) do nothing;

-- Uploads only into an unpaid invoice's folder, by that business's billing
-- account, at most 5 files per invoice.
create or replace function public.invoice_proof_upload_allowed(p_name text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
      select 1 from public.invoices i
      where i.tenant_id = public.storage_tenant(p_name)
        and i.id::text = split_part(p_name, '/', 2)
        and i.status in ('open', 'overdue')
        and public.has_permission(i.tenant_id, 'billing')
    )
    and (select count(*) from storage.objects o
         where o.bucket_id = 'invoice-proofs'
           and o.name like split_part(p_name, '/', 1) || '/' || split_part(p_name, '/', 2) || '/%') < 5;
$$;

grant execute on function public.invoice_proof_upload_allowed(text) to authenticated;

create policy invoice_proofs_insert on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'invoice-proofs' and coalesce(public.invoice_proof_upload_allowed(name), false)
  );

-- The business (billing) and platform admins can view; nobody else.
create policy invoice_proofs_select on storage.objects
  for select to authenticated
  using (
    bucket_id = 'invoice-proofs'
    and coalesce(public.has_permission(public.storage_tenant(name), 'billing'), false)
  );

-- ---------------------------------------------------------------------------
-- The business sends proof for an unpaid invoice.
-- ---------------------------------------------------------------------------
create or replace function public.submit_invoice_payment(
  p_invoice_id uuid,
  p_method text,
  p_proof_path text,
  p_transaction_reference text default ''
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_invoice public.invoices;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id for update;
  if not found or not public.has_permission(v_invoice.tenant_id, 'billing') then
    raise exception 'Invoice not found' using errcode = 'P0002';
  end if;
  if v_invoice.status not in ('open', 'overdue') then
    raise exception 'This invoice doesn''t need paying.' using errcode = 'P0001';
  end if;
  if p_method not in ('gcash', 'maya', 'bank_transfer') then
    raise exception 'Choose how you paid.' using errcode = '22023';
  end if;
  if char_length(coalesce(p_transaction_reference, '')) > 100 then
    raise exception 'The reference number is too long.' using errcode = 'P0001';
  end if;
  if p_proof_path is null
     or p_proof_path not like v_invoice.tenant_id::text || '/' || v_invoice.id::text || '/%'
     or not exists (
       select 1 from storage.objects where bucket_id = 'invoice-proofs' and name = p_proof_path
     ) then
    raise exception 'Upload your proof of payment first.' using errcode = 'P0001';
  end if;

  update public.invoices
  set payment_method = p_method,
      proof_path = p_proof_path,
      transaction_reference = coalesce(btrim(p_transaction_reference), ''),
      proof_submitted_at = now(),
      review_note = ''
  where id = p_invoice_id;

  perform public.log_activity(v_invoice.tenant_id, 'payment',
    format('Sent proof of payment for invoice %s', v_invoice.number));
end;
$$;

-- ---------------------------------------------------------------------------
-- Marking an invoice paid is Sideline's call now (manual payments are
-- checked by a person). Same effect as before: a paid-up past_due
-- business goes back to active.
-- ---------------------------------------------------------------------------
create or replace function public.mark_invoice_paid(p_invoice_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_invoice public.invoices;
begin
  if not public.is_platform_admin() then
    raise exception 'Sideline confirms payments. Send your proof of payment instead.'
      using errcode = '42501';
  end if;
  select * into v_invoice from public.invoices where id = p_invoice_id for update;
  if not found then
    raise exception 'Invoice not found' using errcode = 'P0002';
  end if;
  if v_invoice.status = 'paid' then
    return;
  end if;
  if v_invoice.status = 'void' then
    raise exception 'This invoice was voided.' using errcode = 'P0001';
  end if;

  update public.invoices
  set status = 'paid', paid_at = public.local_today(), proof_submitted_at = null, review_note = ''
  where id = p_invoice_id;

  if not exists (
    select 1 from public.invoices
    where subscription_id = v_invoice.subscription_id and status = 'overdue'
  ) then
    update public.subscriptions set status = 'active'
    where id = v_invoice.subscription_id and status = 'past_due';
    update public.tenants set status = 'active'
    where id = v_invoice.tenant_id and status = 'past_due';
  end if;
  perform public.log_activity(v_invoice.tenant_id, 'payment', format('Paid invoice %s', v_invoice.number));
end;
$$;

-- Platform admin approves a sent proof (invoice paid) or declines it with
-- a reason, which the business sees before sending a new one.
create or replace function public.review_invoice_payment(
  p_invoice_id uuid, p_approve boolean, p_note text default ''
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_invoice public.invoices;
begin
  if not public.is_platform_admin() then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;
  select * into v_invoice from public.invoices where id = p_invoice_id for update;
  if not found then
    raise exception 'Invoice not found' using errcode = 'P0002';
  end if;
  if v_invoice.proof_submitted_at is null or v_invoice.status not in ('open', 'overdue') then
    raise exception 'There''s no payment proof waiting on this invoice.' using errcode = 'P0001';
  end if;

  if p_approve then
    perform public.mark_invoice_paid(p_invoice_id);
  else
    if btrim(coalesce(p_note, '')) = '' then
      raise exception 'Tell the business why the proof was declined.' using errcode = 'P0001';
    end if;
    update public.invoices
    set proof_submitted_at = null, review_note = left(btrim(p_note), 500)
    where id = p_invoice_id;
    perform public.log_activity(v_invoice.tenant_id, 'support',
      format('Payment proof for invoice %s was declined', v_invoice.number));
  end if;
end;
$$;

revoke execute on function
  public.submit_invoice_payment(uuid, text, text, text),
  public.review_invoice_payment(uuid, boolean, text)
from public;
grant execute on function
  public.submit_invoice_payment(uuid, text, text, text),
  public.review_invoice_payment(uuid, boolean, text)
to authenticated;

-- ===========================================================================
-- 20261101102100_trial_requests.sql
-- ===========================================================================

-- Purpose: "Start your free trial" on the marketing site. Trials aren't
-- self-serve: a court owner sends a request (Contact page), a platform
-- admin follows up and adds the business (which starts its trial), then
-- marks the request converted — or declined.

create table public.trial_requests (
  id uuid primary key default gen_random_uuid(),
  business_name text not null check (char_length(business_name) between 1 and 100),
  contact_name text not null check (char_length(contact_name) between 1 and 100),
  email text not null check (char_length(email) <= 254 and email ~ '^\S+@\S+\.\S+$'),
  phone text not null default '' check (char_length(phone) <= 30),
  city text not null default '' check (char_length(city) <= 60),
  courts integer check (courts between 1 and 500),
  message text not null default '' check (char_length(message) <= 1000),
  status text not null default 'new'
    check (status in ('new', 'contacted', 'converted', 'declined')),
  created_at timestamptz not null default now(),
  handled_at timestamptz,
  handled_by uuid references auth.users (id) on delete set null
);

create index trial_requests_created_idx on public.trial_requests (created_at desc);

alter table public.trial_requests enable row level security;

-- Platform admins only; requests come in through submit_trial_request().
create policy trial_requests_select on public.trial_requests
  for select to authenticated using (public.is_platform_admin());
grant select on public.trial_requests to authenticated;

-- Public (signed out). Limited per network and per email address.
create or replace function public.submit_trial_request(
  p_business_name text,
  p_contact_name text,
  p_email text,
  p_phone text default '',
  p_city text default '',
  p_courts integer default null,
  p_message text default ''
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_id uuid;
begin
  if btrim(coalesce(p_business_name, '')) = '' or btrim(coalesce(p_contact_name, '')) = '' then
    raise exception 'Enter your business name and your name.' using errcode = 'P0001';
  end if;
  if v_email !~ '^\S+@\S+\.\S+$' then
    raise exception 'Enter a valid email address.' using errcode = 'P0001';
  end if;
  if p_courts is not null and (p_courts < 1 or p_courts > 500) then
    raise exception 'Enter how many courts you have (1–500).' using errcode = 'P0001';
  end if;
  perform public.hit_rate_limit('trial:ip', public.client_ip(), 5, interval '1 hour');
  perform public.hit_rate_limit('trial:email', v_email, 3, interval '1 day');

  insert into public.trial_requests (business_name, contact_name, email, phone, city, courts, message)
  values (
    left(btrim(p_business_name), 100),
    left(btrim(p_contact_name), 100),
    left(v_email, 254),
    left(btrim(coalesce(p_phone, '')), 30),
    left(btrim(coalesce(p_city, '')), 60),
    p_courts,
    left(btrim(coalesce(p_message, '')), 1000)
  )
  returning id into v_id;
  return v_id;
end;
$$;

-- Platform admin moves a request along.
create or replace function public.set_trial_request_status(p_request_id uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.is_platform_admin() then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;
  if p_status not in ('new', 'contacted', 'converted', 'declined') then
    raise exception 'Unknown status' using errcode = '22023';
  end if;
  update public.trial_requests
  set status = p_status,
      handled_at = case when p_status = 'new' then null else now() end,
      handled_by = case when p_status = 'new' then null else (select auth.uid()) end
  where id = p_request_id;
  if not found then
    raise exception 'Request not found' using errcode = 'P0002';
  end if;
end;
$$;

revoke execute on function
  public.submit_trial_request(text, text, text, text, text, integer, text),
  public.set_trial_request_status(uuid, text)
from public;
grant execute on function public.submit_trial_request(text, text, text, text, text, integer, text)
  to anon, authenticated;
grant execute on function public.set_trial_request_status(uuid, text) to authenticated;

-- ===========================================================================
-- 20261101102200_paymongo_checkout.sql
-- ===========================================================================

-- Purpose: pay invoices online with PayMongo Checkout, confirmed
-- automatically (no proof upload, no admin review). Runs next to the
-- manual proof flow, which is unchanged.
--
-- Flow: the business clicks "Pay online"; the invoice-checkout Edge
-- Function creates a PayMongo checkout session (the invoice id in its
-- metadata) and stores its id here. When PayMongo reports the payment
-- (paymongo-webhook Edge Function, or invoice-checkout's "sync" when the
-- business lands back on CourtDesk), the server calls
-- record_invoice_online_payment() with the service role key. Browsers can
-- never call it.

alter table public.invoices
  add column paymongo_checkout_id text check (char_length(paymongo_checkout_id) <= 100),
  add column paymongo_payment_id text unique check (char_length(paymongo_payment_id) <= 100);

comment on column public.invoices.paymongo_payment_id is
  'PayMongo payment that settled this invoice (online payment); NULL if paid another way.';

-- ---------------------------------------------------------------------------
-- settle_invoice(): the one place an invoice becomes paid. A paid-up
-- past_due business goes back to active. Internal: no API access.
-- ---------------------------------------------------------------------------
create or replace function public.settle_invoice(p_invoice_id uuid, p_activity text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_invoice public.invoices;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id for update;
  if not found then
    raise exception 'Invoice not found' using errcode = 'P0002';
  end if;
  if v_invoice.status = 'paid' then
    return;
  end if;
  if v_invoice.status = 'void' then
    raise exception 'This invoice was voided.' using errcode = 'P0001';
  end if;

  update public.invoices
  set status = 'paid', paid_at = public.local_today(), proof_submitted_at = null, review_note = ''
  where id = p_invoice_id;

  if not exists (
    select 1 from public.invoices
    where subscription_id = v_invoice.subscription_id and status = 'overdue'
  ) then
    update public.subscriptions set status = 'active'
    where id = v_invoice.subscription_id and status = 'past_due';
    update public.tenants set status = 'active'
    where id = v_invoice.tenant_id and status = 'past_due';
  end if;
  perform public.log_activity(v_invoice.tenant_id, 'payment', format(p_activity, v_invoice.number));
end;
$$;

revoke execute on function public.settle_invoice(uuid, text) from public, anon, authenticated;

-- Same behaviour as before, now through settle_invoice().
create or replace function public.mark_invoice_paid(p_invoice_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.is_platform_admin() then
    raise exception 'Sideline confirms payments. Send your proof of payment instead.'
      using errcode = '42501';
  end if;
  perform public.settle_invoice(p_invoice_id, 'Paid invoice %s');
end;
$$;

-- ---------------------------------------------------------------------------
-- Server only (service role): a PayMongo payment for an invoice succeeded.
-- Safe to call twice for the same payment (webhook + return-page sync).
-- ---------------------------------------------------------------------------
create or replace function public.record_invoice_online_payment(
  p_invoice_id uuid,
  p_checkout_id text,
  p_payment_id text,
  p_amount_centavos integer
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_invoice public.invoices;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id for update;
  if not found then
    raise exception 'Invoice not found' using errcode = 'P0002';
  end if;
  if v_invoice.paymongo_payment_id = p_payment_id then
    return;
  end if;
  if v_invoice.status not in ('open', 'overdue') then
    -- Already settled another way: keep it, but log the extra payment so
    -- Sideline can refund it from the PayMongo dashboard.
    perform public.log_activity(v_invoice.tenant_id, 'support',
      format('Extra online payment %s received for invoice %s (already %s) — refund it in PayMongo',
             p_payment_id, v_invoice.number, v_invoice.status));
    return;
  end if;
  if p_amount_centavos is distinct from v_invoice.amount_centavos then
    raise exception 'Payment amount % does not match invoice % (%).',
      p_amount_centavos, v_invoice.number, v_invoice.amount_centavos using errcode = 'P0001';
  end if;

  update public.invoices
  set paymongo_checkout_id = coalesce(p_checkout_id, paymongo_checkout_id),
      paymongo_payment_id = p_payment_id
  where id = p_invoice_id;
  perform public.settle_invoice(p_invoice_id, 'Paid invoice %s online (PayMongo)');
end;
$$;

revoke execute on function public.record_invoice_online_payment(uuid, text, text, integer)
  from public, anon, authenticated;

-- Supabase's service role (used only by Edge Functions) may call it.
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function
      public.settle_invoice(uuid, text),
      public.record_invoice_online_payment(uuid, text, text, integer)
    to service_role;
  end if;
end;
$$;

-- ===========================================================================
-- 20261101102300_paymongo_checkout_save.sql
-- ===========================================================================

-- Purpose: the invoice-checkout Edge Function saved the PayMongo checkout
-- id with a direct table update, which failed ("permission denied for
-- table invoices") because this project grants table access explicitly
-- and the service role has none on invoices. Save it through a function
-- instead, like record_invoice_online_payment(). Server only.

create or replace function public.set_invoice_checkout(p_invoice_id uuid, p_checkout_id text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if char_length(coalesce(p_checkout_id, '')) not between 1 and 100 then
    raise exception 'Invalid checkout id' using errcode = '22023';
  end if;
  update public.invoices
  set paymongo_checkout_id = p_checkout_id
  where id = p_invoice_id and status in ('open', 'overdue');
  if not found then
    raise exception 'This invoice doesn''t need paying.' using errcode = 'P0001';
  end if;
end;
$$;

revoke execute on function public.set_invoice_checkout(uuid, text) from public, anon, authenticated;

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.set_invoice_checkout(uuid, text) to service_role;
  end if;
end;
$$;

-- ===========================================================================
-- 20261101102400_location_map_amenities.sql
-- ===========================================================================

-- Purpose: a map pin per location (owners drop it on a map; the booking
-- site shows the map and "Get directions"), and limits on amenities now
-- that owners can type their own.

alter table public.locations
  add column latitude numeric(9, 6) check (latitude between -90 and 90),
  add column longitude numeric(9, 6) check (longitude between -180 and 180),
  add constraint locations_pin_complete
    check ((latitude is null) = (longitude is null));

comment on column public.locations.latitude is
  'Map pin set by the owner (WGS84). NULL = no pin; the booking site falls back to the address.';

-- At most 20 amenities, each 1–40 characters.
create or replace function public.valid_amenities(p_amenities text[])
returns boolean
language sql
immutable
set search_path = ''
as $$
  select cardinality(p_amenities) <= 20
    and not exists (
      select 1 from unnest(p_amenities) as a where char_length(btrim(a)) not between 1 and 40
    );
$$;

alter table public.locations
  add constraint locations_amenities_valid check (public.valid_amenities(amenities));

-- ===========================================================================
-- 20261101102500_billing_automation.sql
-- ===========================================================================

-- Purpose: billing that runs itself.
--
-- run_billing_cycle() — daily (pg_cron, 00:05 Manila) or from Super Admin:
--   * trials that ended: first invoice + subscription active (or cancelled
--     if the business chose to cancel);
--   * billing periods that ended: renewal invoice for the next period (or
--     cancelled if set to end);
--   * open invoices past their due date: overdue, and the business past due;
--   * unpaid booking holds that timed out are released.
-- Approving a plan change now also issues the invoice for the new plan.
--
-- Invoices are due INVOICE_DUE_DAYS (7) after the period starts. Each
-- billing period gets at most one (non-void) invoice, so running twice is
-- harmless. Suspended businesses are left alone.

alter table public.invoices add column period_start date;

comment on column public.invoices.period_start is
  'First day of the billing period this invoice covers (automatic invoices). NULL for older/manual ones.';

create unique index invoices_one_per_period
  on public.invoices (subscription_id, period_start)
  where period_start is not null and status <> 'void';

-- ---------------------------------------------------------------------------
-- issue_invoice(): the invoice for one billing period at the plan's price.
-- Returns the new invoice id, or NULL if that period already has one.
-- ---------------------------------------------------------------------------
create or replace function public.issue_invoice(p_subscription_id uuid, p_period_start date)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_sub public.subscriptions;
  v_plan public.plans;
  v_id uuid;
  v_number text;
  v_amount integer;
begin
  select * into v_sub from public.subscriptions where id = p_subscription_id;
  select * into v_plan from public.plans where id = v_sub.plan_id;
  v_amount := case when v_sub.billing_cycle = 'annual'
                   then v_plan.annual_price_centavos else v_plan.monthly_price_centavos end;
  if v_amount <= 0 then
    return null; -- free plan: nothing to bill
  end if;

  insert into public.invoices (tenant_id, subscription_id, plan_id, amount_centavos, status,
                               issued_at, due_at, period_start)
  values (v_sub.tenant_id, v_sub.id, v_sub.plan_id, v_amount, 'open',
          public.local_today(), p_period_start + 7, p_period_start)
  on conflict (subscription_id, period_start) where period_start is not null and status <> 'void'
  do nothing
  returning id, number into v_id, v_number;

  if v_id is not null then
    perform public.log_activity(v_sub.tenant_id, 'support',
      format('Invoice %s issued (%s, %s)', v_number, v_plan.name, v_sub.billing_cycle));
  end if;
  return v_id;
end;
$$;

revoke execute on function public.issue_invoice(uuid, date) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- run_billing_cycle(): see the header. Platform admins may run it by hand;
-- the scheduler runs it as the database owner (no signed-in user).
-- ---------------------------------------------------------------------------
create or replace function public.run_billing_cycle()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_today date := public.local_today();
  v_sub public.subscriptions;
  v_step interval;
  v_issued integer := 0;
  v_trials integer := 0;
  v_renewed integer := 0;
  v_cancelled integer := 0;
  v_overdue integer := 0;
  v_inv record;
begin
  if (select auth.uid()) is not null and not public.is_platform_admin() then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;

  perform public.expire_stale_holds();

  -- 1. Trials that have ended.
  for v_sub in
    select s.* from public.subscriptions s
    join public.tenants t on t.id = s.tenant_id
    where s.status = 'trialing' and s.trial_ends_at <= v_today and t.status <> 'suspended'
    for update of s
  loop
    v_trials := v_trials + 1;
    if v_sub.cancel_at_period_end then
      update public.subscriptions set status = 'cancelled' where id = v_sub.id;
      update public.tenants set status = 'cancelled' where id = v_sub.tenant_id;
      perform public.log_activity(v_sub.tenant_id, 'support', 'Trial ended; plan cancelled');
      v_cancelled := v_cancelled + 1;
      continue;
    end if;
    v_step := case when v_sub.billing_cycle = 'annual' then interval '1 year' else interval '1 month' end;
    update public.subscriptions
    set status = 'active',
        current_period_start = v_sub.trial_ends_at,
        current_period_end = (v_sub.trial_ends_at + v_step)::date
    where id = v_sub.id;
    update public.tenants set status = 'active' where id = v_sub.tenant_id and status = 'trialing';
    if public.issue_invoice(v_sub.id, v_sub.trial_ends_at) is not null then
      v_issued := v_issued + 1;
    end if;
  end loop;

  -- 2. Billing periods that have ended (catches up if runs were missed).
  for v_sub in
    select s.* from public.subscriptions s
    join public.tenants t on t.id = s.tenant_id
    where s.status in ('active', 'past_due') and s.current_period_end <= v_today
      and t.status <> 'suspended'
    for update of s
  loop
    if v_sub.cancel_at_period_end then
      update public.subscriptions set status = 'cancelled' where id = v_sub.id;
      update public.tenants set status = 'cancelled' where id = v_sub.tenant_id;
      perform public.log_activity(v_sub.tenant_id, 'support', 'Plan ended (cancelled at period end)');
      v_cancelled := v_cancelled + 1;
      continue;
    end if;
    v_step := case when v_sub.billing_cycle = 'annual' then interval '1 year' else interval '1 month' end;
    while v_sub.current_period_end <= v_today loop
      v_sub.current_period_start := v_sub.current_period_end;
      v_sub.current_period_end := (v_sub.current_period_end + v_step)::date;
      if public.issue_invoice(v_sub.id, v_sub.current_period_start) is not null then
        v_issued := v_issued + 1;
      end if;
    end loop;
    update public.subscriptions
    set current_period_start = v_sub.current_period_start,
        current_period_end = v_sub.current_period_end
    where id = v_sub.id;
    v_renewed := v_renewed + 1;
  end loop;

  -- 3. Open invoices past their due date.
  for v_inv in
    update public.invoices set status = 'overdue'
    where status = 'open' and due_at < v_today
    returning tenant_id, subscription_id, number
  loop
    v_overdue := v_overdue + 1;
    perform public.log_activity(v_inv.tenant_id, 'payment_failed',
      format('Invoice %s is overdue', v_inv.number));
  end loop;
  update public.subscriptions s set status = 'past_due'
  where s.status = 'active'
    and exists (select 1 from public.invoices i where i.subscription_id = s.id and i.status = 'overdue');
  update public.tenants t set status = 'past_due'
  where t.status = 'active'
    and exists (select 1 from public.subscriptions s where s.tenant_id = t.id and s.status = 'past_due');

  return jsonb_build_object(
    'invoicesIssued', v_issued,
    'trialsEnded', v_trials,
    'renewed', v_renewed,
    'cancelled', v_cancelled,
    'overdue', v_overdue
  );
end;
$$;

revoke execute on function public.run_billing_cycle() from public, anon;
grant execute on function public.run_billing_cycle() to authenticated;

-- ---------------------------------------------------------------------------
-- Approving a plan change also bills the new plan (unless still in trial,
-- where the first invoice comes when the trial ends). change_plan() starts
-- a fresh period today; an unpaid invoice already issued for today's period
-- (e.g. a renewal at the old price) is voided and replaced.
-- ---------------------------------------------------------------------------
create or replace function public.decide_plan_request(
  p_request_id uuid, p_approve boolean, p_note text default ''
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_req public.plan_requests;
  v_sub public.subscriptions;
begin
  if not public.is_platform_admin() then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;
  select * into v_req from public.plan_requests where id = p_request_id for update;
  if not found then
    raise exception 'Request not found' using errcode = 'P0002';
  end if;
  if v_req.status <> 'pending' then
    raise exception 'This request was already handled.' using errcode = 'P0001';
  end if;
  if p_approve then
    perform public.change_plan(v_req.tenant_id, v_req.plan_id, v_req.billing_cycle);
    select * into v_sub from public.subscriptions where tenant_id = v_req.tenant_id;
    if v_sub.status <> 'trialing' then
      update public.invoices
      set status = 'void'
      where subscription_id = v_sub.id and period_start = v_sub.current_period_start
        and status = 'open' and proof_submitted_at is null and paymongo_payment_id is null;
      perform public.issue_invoice(v_sub.id, v_sub.current_period_start);
    end if;
  end if;
  update public.plan_requests
  set status = case when p_approve then 'approved' else 'declined' end,
      decision_note = left(btrim(coalesce(p_note, '')), 500),
      decided_by = (select auth.uid()),
      decided_at = now()
  where id = p_request_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Schedule: every day at 00:05 Asia/Manila (16:05 UTC). Needs the pg_cron
-- extension (Supabase: Database → Extensions / Integrations → Cron). If it
-- can't be enabled here, a NOTICE says so and nothing else fails.
-- ---------------------------------------------------------------------------
do $$
begin
  if not exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    raise notice 'pg_cron is not available: schedule run_billing_cycle() another way.';
    return;
  end if;
  begin
    create extension if not exists pg_cron;
    perform cron.schedule('courtdesk-billing', '5 16 * * *', 'select public.run_billing_cycle()');
  exception when others then
    raise notice 'Could not schedule billing (%). Enable pg_cron in the dashboard, then run: select cron.schedule(''courtdesk-billing'', ''5 16 * * *'', ''select public.run_billing_cycle()'');', sqlerrm;
  end;
end;
$$;

-- ===========================================================================
-- 20261101102600_platform_qrph.sql
-- ===========================================================================

-- Purpose: Sideline's manual payment details get a "QR Ph" option (one QR
-- any bank or e-wallet app can scan, e.g. a PayMongo in-store QR), next to
-- GCash / Maya / bank transfer. Platform accounts and invoice payments only;
-- businesses' own payment methods for players are unchanged.

alter table public.platform_payment_accounts
  drop constraint platform_payment_accounts_method_check,
  add constraint platform_payment_accounts_method_check
    check (method in ('qrph', 'gcash', 'maya', 'bank_transfer'));

alter table public.invoices
  drop constraint invoices_payment_method_check,
  add constraint invoices_payment_method_check
    check (payment_method in ('qrph', 'gcash', 'maya', 'bank_transfer'));

-- Same as before, accepting 'qrph'.
create or replace function public.submit_invoice_payment(
  p_invoice_id uuid,
  p_method text,
  p_proof_path text,
  p_transaction_reference text default ''
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_invoice public.invoices;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id for update;
  if not found or not public.has_permission(v_invoice.tenant_id, 'billing') then
    raise exception 'Invoice not found' using errcode = 'P0002';
  end if;
  if v_invoice.status not in ('open', 'overdue') then
    raise exception 'This invoice doesn''t need paying.' using errcode = 'P0001';
  end if;
  if p_method not in ('qrph', 'gcash', 'maya', 'bank_transfer') then
    raise exception 'Choose how you paid.' using errcode = '22023';
  end if;
  if char_length(coalesce(p_transaction_reference, '')) > 100 then
    raise exception 'The reference number is too long.' using errcode = 'P0001';
  end if;
  if p_proof_path is null
     or p_proof_path not like v_invoice.tenant_id::text || '/' || v_invoice.id::text || '/%'
     or not exists (
       select 1 from storage.objects where bucket_id = 'invoice-proofs' and name = p_proof_path
     ) then
    raise exception 'Upload your proof of payment first.' using errcode = 'P0001';
  end if;

  update public.invoices
  set payment_method = p_method,
      proof_path = p_proof_path,
      transaction_reference = coalesce(btrim(p_transaction_reference), ''),
      proof_submitted_at = now(),
      review_note = ''
  where id = p_invoice_id;

  perform public.log_activity(v_invoice.tenant_id, 'payment',
    format('Sent proof of payment for invoice %s', v_invoice.number));
end;
$$;

-- ===========================================================================
-- 20261101102700_platform_settings.sql
-- ===========================================================================

-- Purpose: Super Admin -> Settings is saved for real. One row of
-- platform-wide settings, readable and writable by platform admins only.
-- Trial length now sets new businesses' trials (create_tenant) and the
-- grace period sets when invoices fall due (issue_invoice); the other
-- values are stored for features that aren't built yet (emails,
-- maintenance mode, auto-suspend, self-serve sign-ups, card trials).

create table public.platform_settings (
  id boolean primary key default true check (id),
  company_name text not null default 'Sideline Technologies Inc.'
    check (char_length(btrim(company_name)) between 1 and 120),
  support_email text not null default 'support@courtdesk.app'
    check (support_email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' and char_length(support_email) <= 120),
  billing_currency text not null default 'PHP' check (billing_currency in ('PHP')),
  trial_days integer not null default 14 check (trial_days between 1 and 90),
  grace_days integer not null default 7 check (grace_days between 0 and 60),
  suspend_after_invoices integer not null default 2 check (suspend_after_invoices between 1 and 3),
  require_card_for_trial boolean not null default false,
  allow_signups boolean not null default false,
  maintenance_mode boolean not null default false,
  email_booking_confirmations boolean not null default true,
  email_invoice_reminders boolean not null default true,
  updated_at timestamptz not null default now()
);

comment on table public.platform_settings is
  'Platform-wide settings (single row, id = true). Platform admins only.';

insert into public.platform_settings (id) values (true) on conflict (id) do nothing;

create trigger set_platform_settings_updated_at
  before update on public.platform_settings
  for each row execute function public.set_updated_at();

alter table public.platform_settings enable row level security;

create policy platform_settings_select on public.platform_settings
  for select to authenticated using (public.is_platform_admin());
create policy platform_settings_update on public.platform_settings
  for update to authenticated
  using (public.is_platform_admin()) with check (public.is_platform_admin());

grant select, update on public.platform_settings to authenticated;

-- ---------------------------------------------------------------------------
-- create_tenant(): same as before, trial length from platform_settings.
-- ---------------------------------------------------------------------------
create or replace function public.create_tenant(
  p_name text,
  p_owner_name text,
  p_owner_email text,
  p_phone text default '',
  p_city text default '',
  p_plan_id text default 'starter',
  p_brand_primary text default '#1f5641'
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant_id uuid;
  v_slug text := public.slugify(p_name);
  v_today date := public.local_today();
  v_monogram text;
  v_trial_days integer := coalesce((select trial_days from public.platform_settings), 14);
begin
  if not public.is_platform_admin() then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;
  if v_slug = '' then
    raise exception 'Enter the business name' using errcode = 'P0001';
  end if;
  if exists (select 1 from public.tenants where slug = v_slug) then
    raise exception 'A business with this name already exists' using errcode = 'P0001', hint = 'conflict';
  end if;

  select upper(string_agg(left(w, 1), ''))
    into v_monogram
  from (select w from regexp_split_to_table(btrim(p_name), '\s+') as w limit 2) words;

  insert into public.tenants (slug, name, legal_name, status, owner_name, owner_email, phone,
                              city, brand_primary, brand_monogram)
  values (v_slug, btrim(p_name), btrim(p_name), 'trialing', btrim(p_owner_name),
          lower(btrim(p_owner_email)), coalesce(p_phone, ''), coalesce(p_city, ''),
          p_brand_primary, left(coalesce(v_monogram, ''), 2))
  returning id into v_tenant_id;

  insert into public.booking_rules (tenant_id) values (v_tenant_id);

  insert into public.subscriptions (tenant_id, plan_id, status, billing_cycle, started_at,
                                    current_period_start, current_period_end, trial_ends_at)
  values (v_tenant_id, p_plan_id, 'trialing', 'monthly', v_today, v_today,
          v_today + v_trial_days, v_today + v_trial_days);

  insert into public.staff_members (tenant_id, name, email, phone, role)
  values (v_tenant_id, btrim(p_owner_name), lower(btrim(p_owner_email)), coalesce(p_phone, ''), 'owner');

  perform public.log_activity(v_tenant_id, 'signup',
    format('Created by platform admin — %s-day trial started', v_trial_days));
  return v_tenant_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- issue_invoice(): same as before, due date = period start + grace period.
-- ---------------------------------------------------------------------------
create or replace function public.issue_invoice(p_subscription_id uuid, p_period_start date)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_sub public.subscriptions;
  v_plan public.plans;
  v_id uuid;
  v_number text;
  v_amount integer;
  v_grace_days integer := coalesce((select grace_days from public.platform_settings), 7);
begin
  select * into v_sub from public.subscriptions where id = p_subscription_id;
  select * into v_plan from public.plans where id = v_sub.plan_id;
  v_amount := case when v_sub.billing_cycle = 'annual'
                   then v_plan.annual_price_centavos else v_plan.monthly_price_centavos end;
  if v_amount <= 0 then
    return null; -- free plan: nothing to bill
  end if;

  insert into public.invoices (tenant_id, subscription_id, plan_id, amount_centavos, status,
                               issued_at, due_at, period_start)
  values (v_sub.tenant_id, v_sub.id, v_sub.plan_id, v_amount, 'open',
          public.local_today(), p_period_start + v_grace_days, p_period_start)
  on conflict (subscription_id, period_start) where period_start is not null and status <> 'void'
  do nothing
  returning id, number into v_id, v_number;

  if v_id is not null then
    perform public.log_activity(v_sub.tenant_id, 'support',
      format('Invoice %s issued (%s, %s)', v_number, v_plan.name, v_sub.billing_cycle));
  end if;
  return v_id;
end;
$$;

revoke execute on function public.issue_invoice(uuid, date) from public, anon, authenticated;

-- ===========================================================================
-- 20261101102800_remove_enterprise_plan.sql
-- ===========================================================================

-- Purpose: drop the hidden Enterprise plan. Large or special clients now get
-- a "Custom" build instead: their own booking software, domain and database,
-- quoted per project by Sideline. That's outside CourtDesk, so it isn't a
-- plan here; the pricing page links it to the Contact form.
--
-- Subscriptions, invoices and plan requests reference plans without
-- cascading, so a plan still in use is kept (hidden) rather than deleted.

do $$
begin
  if exists (select 1 from public.subscriptions where plan_id = 'enterprise')
     or exists (select 1 from public.invoices where plan_id = 'enterprise')
     or exists (select 1 from public.plan_requests
                where plan_id = 'enterprise' or from_plan_id = 'enterprise') then
    update public.plans set is_public = false where id = 'enterprise';
    raise notice 'Enterprise is still used by a business, so it was kept (hidden). Move them to another plan, then delete it.';
  else
    delete from public.plans where id = 'enterprise';
  end if;
end $$;

-- ===========================================================================
-- 20261101102900_branding_all_plans.sql
-- ===========================================================================

-- Purpose: custom branding is on every plan. Starter lists it; Growth stops
-- listing it separately (it already has "Everything in Starter"). Edits made
-- in Super Admin -> Plans & limits are kept: only this one item moves.

update public.plans
set features = array_append(features, 'Custom branding')
where id = 'starter' and not ('Custom branding' = any (features));

update public.plans
set features = array_remove(features, 'Custom branding')
where id <> 'starter';

-- ===========================================================================
-- 20261101103000_remove_email_confirmations.sql
-- ===========================================================================

-- Purpose: CourtDesk doesn't send booking confirmation emails; businesses
-- contact their players themselves. Drop the promise from every plan's
-- feature list (other edits from Super Admin -> Plans & limits are kept).

update public.plans
set features = array_remove(features, 'Email confirmations')
where 'Email confirmations' = any (features);

-- ===========================================================================
-- 20261101103100_plan_coming_soon.sql
-- ===========================================================================

-- Purpose: a plan can be shown as "Coming soon" (Pro, until card payments
-- for businesses exist). It stays on the pricing page with a badge, but
-- businesses can't request it. Toggle it in Super Admin -> Plans & limits.

alter table public.plans add column coming_soon boolean not null default false;

grant update (coming_soon) on public.plans to authenticated;

update public.plans set coming_soon = true where id = 'pro';

-- Same as before, refusing plans that are coming soon.
create or replace function public.request_plan_change(
  p_tenant_id uuid, p_plan_id text, p_billing_cycle text, p_note text default ''
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_sub public.subscriptions;
  v_new public.plans;
  v_item jsonb;
  v_limit integer;
  v_id uuid;
begin
  if not public.has_permission(p_tenant_id, 'billing') then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;
  if p_billing_cycle not in ('monthly', 'annual') then
    raise exception 'Unknown billing cycle' using errcode = '22023';
  end if;
  select * into v_sub from public.subscriptions where tenant_id = p_tenant_id;
  if not found then
    raise exception 'No subscription for this business' using errcode = 'P0002';
  end if;
  select * into v_new from public.plans where id = p_plan_id;
  if not found then
    raise exception 'Plan not found' using errcode = 'P0002';
  end if;
  if not v_new.is_public then
    raise exception 'Contact Sideline to switch to the % plan.', v_new.name using errcode = 'P0001';
  end if;
  if v_new.coming_soon and v_sub.plan_id <> p_plan_id then
    raise exception 'The % plan is coming soon.', v_new.name using errcode = 'P0001';
  end if;
  if v_sub.plan_id = p_plan_id and v_sub.billing_cycle = p_billing_cycle
     and v_sub.status <> 'trialing' then
    raise exception 'You''re already on this plan.' using errcode = 'P0001';
  end if;
  for v_item in select * from jsonb_array_elements(public.compute_usage(p_tenant_id)) loop
    continue when v_item->>'key' = 'bookingsPerMonth';
    v_limit := case v_item->>'key'
      when 'locations' then v_new.limit_locations
      when 'courts' then v_new.limit_courts
    end;
    if v_limit is not null and (v_item->>'used')::integer > v_limit then
      raise exception 'Can''t switch: you''re using % % and the % plan allows %.',
        v_item->>'used', v_item->>'key', v_new.name, v_limit using errcode = 'P0001';
    end if;
  end loop;
  if exists (select 1 from public.plan_requests
             where tenant_id = p_tenant_id and status = 'pending') then
    raise exception 'You already have a plan change request waiting. Cancel it first to send a new one.'
      using errcode = 'P0001', hint = 'conflict';
  end if;

  insert into public.plan_requests (tenant_id, from_plan_id, from_billing_cycle, plan_id,
                                    billing_cycle, note, requested_by)
  values (p_tenant_id, v_sub.plan_id, v_sub.billing_cycle, p_plan_id, p_billing_cycle,
          left(btrim(coalesce(p_note, '')), 500), (select auth.uid()))
  returning id into v_id;

  perform public.log_activity(p_tenant_id, 'support',
    format('Requested a plan change to %s (%s)', v_new.name, p_billing_cycle));
  return v_id;
end;
$$;

-- ===========================================================================
-- 20261101103200_link_confirmed_logins_only.sql
-- ===========================================================================

-- Purpose: a login is linked to a business account (owner or extra
-- account) only once its email address is confirmed. Before, the link was
-- made as soon as an auth user with that email existed, so if public
-- sign-ups were ever switched on, anyone could sign up with an invited
-- owner's email and be linked to that business.
--
-- Users added in Authentication -> Users with "Auto Confirm User" are
-- confirmed at once, so the usual flow is unchanged.

create or replace function public.link_staff_on_signup()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.email is null or new.email_confirmed_at is null then
    return new;
  end if;
  update public.staff_members
  set user_id = new.id,
      status = case when status = 'invited' then 'active' else status end
  where lower(email) = lower(new.email) and user_id is null;
  return new;
end;
$$;

-- Also fire when a user confirms their email.
drop trigger if exists on_auth_user_link_staff on auth.users;
create trigger on_auth_user_link_staff
  after insert or update of email, email_confirmed_at on auth.users
  for each row execute function public.link_staff_on_signup();

create or replace function public.link_staff_to_existing_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid;
begin
  select id into v_user from auth.users
  where lower(email) = lower(new.email) and email_confirmed_at is not null
  limit 1;
  if v_user is not null then
    new.user_id := v_user;
    if new.status = 'invited' then
      new.status := 'active';
    end if;
  end if;
  return new;
end;
$$;

-- ===========================================================================
-- 20261101103300_walk_ins_setting.sql
-- ===========================================================================

-- Purpose: "Accept walk-ins at the front desk" (booking_rules.allow_walk_ins)
-- now does something: when it's off, no booking can be created with the
-- walk-in source. Online and phone bookings are unaffected.

-- Same as before (20261101101900_abuse_protection.sql), plus the walk-in check.
create or replace function public.create_booking_group(
  p_tenant_id uuid,
  p_slots jsonb,
  p_customer_name text,
  p_customer_phone text,
  p_customer_email text default '',
  p_players integer default 4,
  p_notes text default '',
  p_source text default 'online',
  p_payment_method text default null,
  p_payment_pending boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_open integer;
begin
  if p_source = 'walk_in'
     and not coalesce((select allow_walk_ins from public.booking_rules where tenant_id = p_tenant_id), true) then
    raise exception 'This business doesn''t take walk-ins. Turn them on in Settings → Booking rules.'
      using errcode = 'P0001';
  end if;
  if p_source = 'online' and not public.has_permission(p_tenant_id, 'bookings') then
    perform public.expire_stale_holds();
    -- Unpaid upcoming online bookings (counted per reference) for this phone.
    select count(distinct b.reference) into v_open
    from public.bookings b
    join public.customers c on c.id = b.customer_id
    where b.tenant_id = p_tenant_id
      and b.source = 'online'
      and b.status in ('pending', 'confirmed')
      and b.payment_status = 'unpaid'
      and b.business_date >= public.local_today()
      and char_length(public.phone_key(p_customer_phone)) = 10
      and public.phone_key(c.phone) = public.phone_key(p_customer_phone);
    if v_open >= 3 then
      raise exception 'This number already has 3 unpaid bookings here. Pay for or cancel one first, or contact the venue.'
        using errcode = 'P0001', hint = 'rate_limited';
    end if;
    perform public.hit_rate_limit('booking', p_tenant_id::text || '|' || public.client_ip(),
                                  15, interval '1 hour');
  end if;
  return public.create_booking_group_core(p_tenant_id, p_slots, p_customer_name, p_customer_phone,
    p_customer_email, p_players, p_notes, p_source, p_payment_method, p_payment_pending);
end;
$$;

-- ===========================================================================
-- 20261101103400_narrow_public_bucket_select.sql
-- ===========================================================================

-- Purpose: stop anyone from listing every file in the public buckets
-- "payment-qr" and "branding" (Supabase security advisor: "Clients can list
-- all files in this bucket").
--
-- Public buckets serve files by URL without any policy, so the booking site
-- and QR codes keep loading. The SELECT policy is still needed by the people
-- who manage the files: Storage's remove() only deletes rows they can select.
-- So SELECT now matches who may delete: the business (settings permission)
-- for its own folder, and platform admins for Sideline's QR (sideline/...).

drop policy if exists payment_qr_select on storage.objects;
create policy payment_qr_select on storage.objects
  for select to authenticated
  using (
    bucket_id = 'payment-qr'
    and (
      coalesce(public.has_permission(public.payment_qr_tenant(name), 'settings'), false)
      or (name like 'sideline/%' and public.is_platform_admin())
    )
  );

drop policy if exists branding_select on storage.objects;
create policy branding_select on storage.objects
  for select to authenticated
  using (
    bucket_id = 'branding'
    and coalesce(public.has_permission(public.storage_tenant(name), 'settings'), false)
  );

-- ===========================================================================
-- 20261101103500_customer_tag_lists.sql
-- ===========================================================================

-- Purpose: each business picks its own customer tags (Customers → Manage
-- tags) instead of one fixed list for everyone.
--
-- Its own table, not a tenants column: tenants is readable by anyone (the
-- booking site loads it), and tag names like "Late payer" are internal.
-- No row = the default list. "New" is built in (added automatically to
-- first-time bookers) and isn't stored here.
--
-- Removing a tag from the list doesn't strip it from customers who have it;
-- the customer form still shows it there so it can be unticked.

-- True when tags is at most 20 distinct (case-insensitive) names of 1–24
-- characters, none of them "New".
create or replace function public.valid_customer_tags(tags text[])
returns boolean
language sql
immutable
set search_path = ''
as $$
  select coalesce(cardinality(tags), 0) <= 20
    and coalesce((
      select bool_and(char_length(btrim(t)) between 1 and 24 and t = btrim(t) and lower(t) <> 'new')
        and count(distinct lower(t)) = count(*)
      from unnest(tags) as t
    ), true);
$$;

create table public.customer_tag_lists (
  tenant_id uuid primary key references public.tenants (id) on delete cascade,
  tags text[] not null default array['Regular', 'Member', 'League', 'Clinic', 'Corporate'],
  updated_at timestamptz not null default now(),
  constraint customer_tag_lists_valid check (public.valid_customer_tags(tags))
);

comment on table public.customer_tag_lists is
  'Customer tags a business can pick from (besides the built-in "New"). Private to the business.';

create trigger set_customer_tag_lists_updated_at
  before update on public.customer_tag_lists
  for each row execute function public.set_updated_at();

alter table public.customer_tag_lists enable row level security;

create policy customer_tag_lists_select on public.customer_tag_lists
  for select to authenticated using (public.has_permission(tenant_id, 'customers'));
create policy customer_tag_lists_insert on public.customer_tag_lists
  for insert to authenticated with check (public.has_permission(tenant_id, 'customers'));
create policy customer_tag_lists_update on public.customer_tag_lists
  for update to authenticated
  using (public.has_permission(tenant_id, 'customers'))
  with check (public.has_permission(tenant_id, 'customers'));

grant select, insert (tenant_id, tags), update (tags) on public.customer_tag_lists to authenticated;

-- ===========================================================================
-- 20261101103600_per_player_booking_limits.sql
-- ===========================================================================

-- Purpose: two per-player limits for online bookings, set by each business
-- under Settings → Booking rules:
--
--   * max_court_hours_per_day: the most hours one phone number can hold on
--     one court on one day, across all its bookings ("Add date" can't stack
--     the same court past it). NULL = no limit (the old behaviour).
--   * max_unpaid_bookings: how many unpaid upcoming bookings one phone
--     number can hold before it must pay or cancel one. Was a fixed 3.
--
-- Staff bookings (walk-in, phone, or online made by staff) are not limited,
-- same as the other abuse limits.

alter table public.booking_rules
  add column max_court_hours_per_day smallint
    check (max_court_hours_per_day between 1 and 12),
  add column max_unpaid_bookings smallint not null default 3
    check (max_unpaid_bookings between 1 and 10),
  -- A single booking may already be as long as the longest booking.
  add constraint booking_rules_court_day_cap
    check (max_court_hours_per_day is null or max_court_hours_per_day * 60 >= max_duration_minutes);

comment on column public.booking_rules.max_court_hours_per_day is
  'Most hours one player (phone) can book on one court per day, online. NULL = no limit.';
comment on column public.booking_rules.max_unpaid_bookings is
  'Unpaid upcoming online bookings one player (phone) can hold at once.';

-- Same as before (20261101103300_walk_ins_setting.sql), with the unpaid limit
-- read from the rules and the per-court daily limit added.
create or replace function public.create_booking_group(
  p_tenant_id uuid,
  p_slots jsonb,
  p_customer_name text,
  p_customer_phone text,
  p_customer_email text default '',
  p_players integer default 4,
  p_notes text default '',
  p_source text default 'online',
  p_payment_method text default null,
  p_payment_pending boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_rules public.booking_rules;
  v_open integer;
  v_over record;
begin
  select * into v_rules from public.booking_rules where tenant_id = p_tenant_id;
  if p_source = 'walk_in' and not coalesce(v_rules.allow_walk_ins, true) then
    raise exception 'This business doesn''t take walk-ins. Turn them on in Settings → Booking rules.'
      using errcode = 'P0001';
  end if;
  if p_source = 'online' and not public.has_permission(p_tenant_id, 'bookings') then
    perform public.expire_stale_holds();
    -- Unpaid upcoming online bookings (counted per reference) for this phone.
    select count(distinct b.reference) into v_open
    from public.bookings b
    join public.customers c on c.id = b.customer_id
    where b.tenant_id = p_tenant_id
      and b.source = 'online'
      and b.status in ('pending', 'confirmed')
      and b.payment_status = 'unpaid'
      and b.business_date >= public.local_today()
      and char_length(public.phone_key(p_customer_phone)) = 10
      and public.phone_key(c.phone) = public.phone_key(p_customer_phone);
    if v_open >= coalesce(v_rules.max_unpaid_bookings, 3) then
      raise exception 'This number already has % unpaid % here. Pay for or cancel one first, or contact the venue.',
        v_open, case when v_open = 1 then 'booking' else 'bookings' end
        using errcode = 'P0001', hint = 'rate_limited';
    end if;

    -- Hours per court per day: this request plus what the phone already holds.
    if v_rules.max_court_hours_per_day is not null and jsonb_typeof(p_slots) = 'array' then
      select r.court_id, r.business_date, ct.name as court_name into v_over
      from (
        select (s->>'courtId')::uuid as court_id,
               (s->>'date')::date as business_date,
               sum((s->>'durationHours')::integer) as hours
        from jsonb_array_elements(p_slots) as s
        group by 1, 2
      ) r
      join public.courts ct on ct.id = r.court_id and ct.tenant_id = p_tenant_id
      where r.hours + coalesce((
          select sum(b.duration_hours)
          from public.bookings b
          join public.customers c on c.id = b.customer_id
          where b.tenant_id = p_tenant_id
            and b.court_id = r.court_id
            and b.business_date = r.business_date
            and b.status in ('pending', 'confirmed')
            and char_length(public.phone_key(p_customer_phone)) = 10
            and public.phone_key(c.phone) = public.phone_key(p_customer_phone)
        ), 0) > v_rules.max_court_hours_per_day
      limit 1;
      if found then
        raise exception 'You can book up to % % on % per day (%). Pick another court or day.',
          v_rules.max_court_hours_per_day,
          case when v_rules.max_court_hours_per_day = 1 then 'hour' else 'hours' end,
          v_over.court_name, to_char(v_over.business_date, 'Mon FMDD')
          using errcode = 'P0001', hint = 'rate_limited';
      end if;
    end if;

    perform public.hit_rate_limit('booking', p_tenant_id::text || '|' || public.client_ip(),
                                  15, interval '1 hour');
  end if;
  return public.create_booking_group_core(p_tenant_id, p_slots, p_customer_name, p_customer_phone,
    p_customer_email, p_players, p_notes, p_source, p_payment_method, p_payment_pending);
end;
$$;

-- ===========================================================================
-- 20261101103700_booking_limits_precheck.sql
-- ===========================================================================

-- Purpose: let the booking site check the per-player limits once, when the
-- player clicks Continue on "Your details" (the first moment their phone
-- number is known), instead of only at the final submit.
--
-- The checks move into assert_player_limits() so booking and pre-check
-- share one copy:
--   * create_booking_group() calls it, as before (the real guard);
--   * check_player_limits() is the public pre-check: one call per booking
--     attempt, rate limited per network so it can't be used to probe phone
--     numbers in bulk.

-- Raises the player-facing message if this phone may not book these slots
-- online. Internal: not callable through the API.
create or replace function public.assert_player_limits(
  p_tenant_id uuid,
  p_slots jsonb,
  p_customer_phone text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_rules public.booking_rules;
  v_open integer;
  v_over record;
begin
  select * into v_rules from public.booking_rules where tenant_id = p_tenant_id;
  if char_length(public.phone_key(p_customer_phone)) <> 10 then
    return; -- the booking itself rejects a bad number
  end if;

  -- Unpaid upcoming online bookings (counted per reference) for this phone.
  select count(distinct b.reference) into v_open
  from public.bookings b
  join public.customers c on c.id = b.customer_id
  where b.tenant_id = p_tenant_id
    and b.source = 'online'
    and b.status in ('pending', 'confirmed')
    and b.payment_status = 'unpaid'
    and b.business_date >= public.local_today()
    and public.phone_key(c.phone) = public.phone_key(p_customer_phone);
  if v_open >= coalesce(v_rules.max_unpaid_bookings, 3) then
    raise exception 'This number already has % unpaid % here. Pay for or cancel one first, or contact the venue.',
      v_open, case when v_open = 1 then 'booking' else 'bookings' end
      using errcode = 'P0001', hint = 'rate_limited';
  end if;

  -- Hours per court per day: these slots plus what the phone already holds.
  if v_rules.max_court_hours_per_day is not null and jsonb_typeof(p_slots) = 'array' then
    select r.court_id, r.business_date, ct.name as court_name into v_over
    from (
      select (s->>'courtId')::uuid as court_id,
             (s->>'date')::date as business_date,
             sum((s->>'durationHours')::integer) as hours
      from jsonb_array_elements(p_slots) as s
      group by 1, 2
    ) r
    join public.courts ct on ct.id = r.court_id and ct.tenant_id = p_tenant_id
    where r.hours + coalesce((
        select sum(b.duration_hours)
        from public.bookings b
        join public.customers c on c.id = b.customer_id
        where b.tenant_id = p_tenant_id
          and b.court_id = r.court_id
          and b.business_date = r.business_date
          and b.status in ('pending', 'confirmed')
          and public.phone_key(c.phone) = public.phone_key(p_customer_phone)
      ), 0) > v_rules.max_court_hours_per_day
    limit 1;
    if found then
      raise exception 'You can book up to % % on % per day (%). Pick another court or day.',
        v_rules.max_court_hours_per_day,
        case when v_rules.max_court_hours_per_day = 1 then 'hour' else 'hours' end,
        v_over.court_name, to_char(v_over.business_date, 'Mon FMDD')
        using errcode = 'P0001', hint = 'rate_limited';
    end if;
  end if;
end;
$$;

revoke execute on function public.assert_player_limits(uuid, jsonb, text)
  from public, anon, authenticated;

-- Same as before (20261101103600_per_player_booking_limits.sql), with the
-- limits read from assert_player_limits().
create or replace function public.create_booking_group(
  p_tenant_id uuid,
  p_slots jsonb,
  p_customer_name text,
  p_customer_phone text,
  p_customer_email text default '',
  p_players integer default 4,
  p_notes text default '',
  p_source text default 'online',
  p_payment_method text default null,
  p_payment_pending boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_source = 'walk_in'
     and not coalesce((select allow_walk_ins from public.booking_rules where tenant_id = p_tenant_id), true) then
    raise exception 'This business doesn''t take walk-ins. Turn them on in Settings → Booking rules.'
      using errcode = 'P0001';
  end if;
  if p_source = 'online' and not public.has_permission(p_tenant_id, 'bookings') then
    perform public.expire_stale_holds();
    perform public.assert_player_limits(p_tenant_id, p_slots, p_customer_phone);
    perform public.hit_rate_limit('booking', p_tenant_id::text || '|' || public.client_ip(),
                                  15, interval '1 hour');
  end if;
  return public.create_booking_group_core(p_tenant_id, p_slots, p_customer_name, p_customer_phone,
    p_customer_email, p_players, p_notes, p_source, p_payment_method, p_payment_pending);
end;
$$;

-- The booking site's pre-check. Returns nothing when the player may go on,
-- raises the same message the booking would otherwise. Staff aren't limited.
create or replace function public.check_player_limits(
  p_tenant_id uuid,
  p_slots jsonb,
  p_customer_phone text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if public.has_permission(p_tenant_id, 'bookings') then
    return;
  end if;
  perform public.hit_rate_limit('booking_check', p_tenant_id::text || '|' || public.client_ip(),
                                30, interval '10 minutes');
  perform public.expire_stale_holds();
  perform public.assert_player_limits(p_tenant_id, p_slots, p_customer_phone);
end;
$$;

grant execute on function public.check_player_limits(uuid, jsonb, text) to anon, authenticated;

-- ===========================================================================
-- 20261101103800_collected_by_payment_date.sql
-- ===========================================================================

-- Purpose: "Collected today / this month" on the business dashboard count
-- money on the day it was received (a proof approved, or a payment
-- recorded), not on the day the court is played.
--
--   * payments.paid_at: set when a payment becomes paid. Existing paid rows
--     get their last update time, the closest record we have.
--   * tenant_collected(): today, yesterday, this month and last month up to
--     the same day, in one call. Refunded payments don't count.

alter table public.payments add column paid_at timestamptz;

update public.payments set paid_at = updated_at where status = 'paid' and paid_at is null;

comment on column public.payments.paid_at is
  'When the payment became paid (proof approved or payment recorded). NULL while not paid.';

create or replace function public.payments_set_paid_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.status = 'paid' and (tg_op = 'INSERT' or old.status is distinct from 'paid') then
    new.paid_at := now();
  elsif new.status <> 'paid' and new.status <> 'refunded' then
    new.paid_at := null;
  end if;
  return new;
end;
$$;

create trigger set_payments_paid_at
  before insert or update of status on public.payments
  for each row execute function public.payments_set_paid_at();

create index payments_tenant_paid_idx on public.payments (tenant_id, paid_at) where status = 'paid';

-- Amounts in centavos, by Manila calendar day of paid_at.
create or replace function public.tenant_collected(p_tenant_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_today date := public.local_today();
  v_month date := date_trunc('month', public.local_today())::date;
  v_last_month date := (date_trunc('month', public.local_today()) - interval '1 month')::date;
begin
  if not public.has_permission(p_tenant_id, 'dashboard') then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;
  return (
    with p as (
      select amount_centavos as amount, (paid_at at time zone 'Asia/Manila')::date as day
      from public.payments
      where tenant_id = p_tenant_id
        and status = 'paid'
        and paid_at >= (v_last_month::timestamp at time zone 'Asia/Manila')
    )
    select jsonb_build_object(
      'today', coalesce(sum(amount) filter (where day = v_today), 0),
      'yesterday', coalesce(sum(amount) filter (where day = v_today - 1), 0),
      'month', coalesce(sum(amount) filter (where day >= v_month), 0),
      -- Same number of days into last month, so the comparison is fair.
      'lastMonthToDate', coalesce(sum(amount) filter (
        where day >= v_last_month
          and day <= least(v_last_month + (v_today - v_month), v_month - 1)
      ), 0)
    )
    from p
  );
end;
$$;

revoke execute on function public.tenant_collected(uuid) from public, anon;
grant execute on function public.tenant_collected(uuid) to authenticated;

-- ===========================================================================
-- 20261101103900_remove_players.sql
-- ===========================================================================

-- Purpose: bookings no longer record a number of players. Nothing asks for
-- it any more (booking site or staff form), so the column, and the
-- p_players argument of create_booking_group(), go.
--
-- create_booking_group() changes signature, so it and its internal core are
-- dropped and recreated (same behaviour as 20261101103700 and
-- 20261101100800, minus players). booking_rows selects b.*, so it's
-- recreated around the column drop.

drop function public.create_booking_group(uuid, jsonb, text, text, text, integer, text, text, text, boolean);
drop function public.create_booking_group_core(uuid, jsonb, text, text, text, integer, text, text, text, boolean);

drop view public.booking_rows;
alter table public.bookings drop column players;

create view public.booking_rows
with (security_invoker = true) as
select
  b.*,
  c.name as customer_name,
  c.phone as customer_phone,
  ct.name as court_name,
  l.name as location_name
from public.bookings b
join public.customers c on c.id = b.customer_id
join public.courts ct on ct.id = b.court_id
join public.locations l on l.id = b.location_id;

grant select on public.booking_rows to authenticated;

-- ---------------------------------------------------------------------------
-- The booking engine (internal): validates every slot, then inserts them all
-- under one reference. See 20261101100800_booking_functions.sql.
-- ---------------------------------------------------------------------------
create function public.create_booking_group_core(
  p_tenant_id uuid,
  p_slots jsonb,
  p_customer_name text,
  p_customer_phone text,
  p_customer_email text default '',
  p_notes text default '',
  p_source text default 'online',
  p_payment_method text default null,
  p_payment_pending boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant public.tenants;
  v_rules public.booking_rules;
  v_is_staff boolean := public.has_permission(p_tenant_id, 'bookings');
  v_today date;
  v_now_hour integer;
  v_count integer;
  v_slot record;
  v_court record;
  v_limit integer;
  v_month record;
  v_customer_id uuid;
  v_method text := nullif(p_payment_method, '');
  v_paid_now boolean;
  v_status text;
  v_reference text;
  v_group_id uuid;
  v_payment_reference text;
  v_booking_id uuid;
  v_amount integer;
  v_total integer := 0;
  v_ids uuid[] := '{}';
begin
  perform public.expire_stale_holds();

  select * into v_tenant from public.tenants where id = p_tenant_id;
  if not found then
    raise exception 'Business not found' using errcode = 'P0002';
  end if;
  if v_tenant.status in ('suspended', 'cancelled') then
    raise exception '% is not taking bookings at the moment.', v_tenant.name using errcode = 'P0001';
  end if;
  if p_source not in ('online', 'walk_in', 'phone') then
    raise exception 'Unknown booking source' using errcode = '22023';
  end if;
  if p_source <> 'online' and not v_is_staff then
    raise exception 'You don''t have permission to do that.' using errcode = '42501';
  end if;

  select * into v_rules from public.booking_rules where tenant_id = p_tenant_id;
  v_today := public.local_today(v_tenant.timezone);
  v_now_hour := extract(hour from now() at time zone v_tenant.timezone)::integer;

  -- Payment: online cash means "pay at the venue" (only when allowed).
  if p_source = 'online' and not v_is_staff then
    if v_method is not null and not (v_method = any (v_rules.payment_methods)) then
      raise exception 'That payment method isn''t accepted here.' using errcode = 'P0001';
    end if;
    if v_method = 'cash' then
      if v_rules.require_prepayment then
        raise exception 'This business needs payment before the booking is confirmed.' using errcode = 'P0001';
      end if;
      v_method := null;
    end if;
    v_paid_now := false;
  else
    v_paid_now := v_method is not null and not coalesce(p_payment_pending, false);
  end if;

  -- Customer details
  if char_length(btrim(coalesce(p_customer_name, ''))) < 2 or p_customer_name ~ '[<>]' then
    raise exception 'Please enter your name.' using errcode = 'P0001';
  end if;
  if char_length(public.phone_key(p_customer_phone)) <> 10 then
    raise exception 'Please enter a valid mobile number.' using errcode = 'P0001';
  end if;
  if char_length(coalesce(p_notes, '')) > 500 then
    raise exception 'Notes are too long (500 characters max).' using errcode = 'P0001';
  end if;

  -- Slots
  if jsonb_typeof(p_slots) <> 'array' then
    raise exception 'Pick at least one time.' using errcode = '22023';
  end if;
  v_count := jsonb_array_length(p_slots);
  if v_count = 0 then
    raise exception 'Pick at least one time.' using errcode = 'P0001';
  end if;
  if v_count > 7 then
    raise exception 'One booking can cover up to 7 dates.' using errcode = 'P0001';
  end if;

  for v_slot in
    select (s->>'courtId')::uuid as court_id,
           (s->>'date')::date as business_date,
           (s->>'startHour')::integer as start_hour,
           (s->>'durationHours')::integer as duration_hours
    from jsonb_array_elements(p_slots) as s
  loop
    select c.status, c.name, l.status as location_status, l.open_hour, l.close_hour
      into v_court
    from public.courts c
    join public.locations l on l.id = c.location_id
    where c.id = v_slot.court_id and c.tenant_id = p_tenant_id;
    if not found then
      raise exception 'Court not found' using errcode = 'P0002';
    end if;
    if v_court.status <> 'active' or v_court.location_status <> 'active' then
      raise exception '% is not open for bookings right now.', v_court.name using errcode = 'P0001';
    end if;
    if v_slot.duration_hours < 1
       or v_slot.start_hour < v_court.open_hour
       or v_slot.start_hour + v_slot.duration_hours > v_court.close_hour then
      raise exception 'That time is outside opening hours.' using errcode = 'P0001';
    end if;
    if p_source = 'online' and not v_is_staff then
      if v_slot.duration_hours * 60 < v_rules.min_duration_minutes
         or v_slot.duration_hours * 60 > v_rules.max_duration_minutes then
        raise exception 'That booking length is not allowed.' using errcode = 'P0001';
      end if;
      if v_slot.business_date > v_today + v_rules.advance_booking_days then
        raise exception 'Bookings open % days ahead.', v_rules.advance_booking_days using errcode = 'P0001';
      end if;
      if v_slot.business_date < v_today
         or (v_slot.business_date = v_today and v_slot.start_hour <= v_now_hour) then
        raise exception 'That time has already passed.' using errcode = 'P0001';
      end if;
    end if;
  end loop;

  if exists (
    select 1
    from jsonb_array_elements(p_slots) with ordinality as a (s, i)
    join jsonb_array_elements(p_slots) with ordinality as b (s, j) on a.i < b.j
    where a.s->>'courtId' = b.s->>'courtId'
      and a.s->>'date' = b.s->>'date'
      and (a.s->>'startHour')::integer < (b.s->>'startHour')::integer + (b.s->>'durationHours')::integer
      and (b.s->>'startHour')::integer < (a.s->>'startHour')::integer + (a.s->>'durationHours')::integer
  ) then
    raise exception 'Two of the picked times overlap on the same court.' using errcode = 'P0001';
  end if;

  -- Monthly booking limit of the plan
  select p.limit_bookings_per_month into v_limit
  from public.subscriptions s join public.plans p on p.id = s.plan_id
  where s.tenant_id = p_tenant_id;
  if v_limit is not null then
    for v_month in
      select date_trunc('month', (s->>'date')::date)::date as month, count(*) as adding
      from jsonb_array_elements(p_slots) as s
      group by 1
    loop
      if (
        select count(*) from public.bookings
        where tenant_id = p_tenant_id and status <> 'cancelled'
          and business_date >= v_month.month
          and business_date < (v_month.month + interval '1 month')::date
      ) + v_month.adding > v_limit then
        raise exception 'This business has reached its monthly booking limit.'
          using errcode = 'P0001', hint = 'limit_reached';
      end if;
    end loop;
  end if;

  -- Customer: one record per phone number per business
  select id into v_customer_id
  from public.customers
  where tenant_id = p_tenant_id and public.phone_key(phone) = public.phone_key(p_customer_phone);
  if v_customer_id is null then
    insert into public.customers (tenant_id, name, email, phone, tags)
    values (p_tenant_id, btrim(p_customer_name), coalesce(btrim(p_customer_email), ''),
            btrim(p_customer_phone), array['New'])
    returning id into v_customer_id;
  end if;

  v_status := case
    when p_source = 'online' and v_rules.require_prepayment and not v_paid_now then 'pending'
    else 'confirmed'
  end;
  v_reference := public.generate_booking_reference(p_tenant_id);
  v_group_id := case when v_count > 1 then gen_random_uuid() end;
  v_payment_reference := case when v_method is not null then public.provider_reference(v_method) end;

  begin
    for v_slot in
      select (s->>'courtId')::uuid as court_id,
             (s->>'date')::date as business_date,
             (s->>'startHour')::integer as start_hour,
             (s->>'durationHours')::integer as duration_hours
      from jsonb_array_elements(p_slots) as s
      order by 2, 3
    loop
      v_amount := public.booking_price(v_slot.court_id, v_slot.business_date,
                                       v_slot.start_hour, v_slot.duration_hours);
      insert into public.bookings (
        tenant_id, location_id, court_id, customer_id, group_id, reference,
        business_date, start_hour, duration_hours, status, payment_status,
        amount_centavos, source, notes, hold_expires_at, created_by
      )
      select p_tenant_id, c.location_id, c.id, v_customer_id, v_group_id, v_reference,
             v_slot.business_date, v_slot.start_hour, v_slot.duration_hours, v_status,
             case when v_paid_now then 'paid' else 'unpaid' end,
             v_amount, p_source, coalesce(p_notes, ''),
             case when v_status = 'pending' and v_method is null
                  then now() + make_interval(mins => v_rules.hold_minutes) end,
             (select auth.uid())
      from public.courts c where c.id = v_slot.court_id
      returning id into v_booking_id;

      if v_method is not null then
        insert into public.payments (tenant_id, booking_id, customer_id, amount_centavos,
                                     method, status, reference, recorded_by)
        values (p_tenant_id, v_booking_id, v_customer_id, v_amount, v_method,
                case when v_paid_now then 'paid' else 'pending' end,
                v_payment_reference, (select auth.uid()));
      end if;

      v_total := v_total + v_amount;
      v_ids := v_ids || v_booking_id;
    end loop;
  exception
    when exclusion_violation then
      raise exception 'That time overlaps another booking on this court.' using errcode = 'P0001';
  end;

  return jsonb_build_object('reference', v_reference, 'total', v_total, 'bookingIds', to_jsonb(v_ids));
end;
$$;

revoke execute on function
  public.create_booking_group_core(uuid, jsonb, text, text, text, text, text, text, boolean)
  from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- The public entry point: walk-in setting, per-player limits and the
-- per-network rate limit, then the core. See 20261101103700.
-- ---------------------------------------------------------------------------
create function public.create_booking_group(
  p_tenant_id uuid,
  p_slots jsonb,
  p_customer_name text,
  p_customer_phone text,
  p_customer_email text default '',
  p_notes text default '',
  p_source text default 'online',
  p_payment_method text default null,
  p_payment_pending boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_source = 'walk_in'
     and not coalesce((select allow_walk_ins from public.booking_rules where tenant_id = p_tenant_id), true) then
    raise exception 'This business doesn''t take walk-ins. Turn them on in Settings → Booking rules.'
      using errcode = 'P0001';
  end if;
  if p_source = 'online' and not public.has_permission(p_tenant_id, 'bookings') then
    perform public.expire_stale_holds();
    perform public.assert_player_limits(p_tenant_id, p_slots, p_customer_phone);
    perform public.hit_rate_limit('booking', p_tenant_id::text || '|' || public.client_ip(),
                                  15, interval '1 hour');
  end if;
  return public.create_booking_group_core(p_tenant_id, p_slots, p_customer_name, p_customer_phone,
    p_customer_email, p_notes, p_source, p_payment_method, p_payment_pending);
end;
$$;

revoke execute on function
  public.create_booking_group(uuid, jsonb, text, text, text, text, text, text, boolean)
  from public;
grant execute on function
  public.create_booking_group(uuid, jsonb, text, text, text, text, text, text, boolean)
  to anon, authenticated;

-- ===========================================================================
-- 20261101104000_plan_prices_nov_2026.sql
-- ===========================================================================

-- Purpose: new plan prices, and "Day & night rates" listed on every plan
-- (every plan already had it; only Growth's feature list said so).
--
--   Starter ₱999/mo   (₱9,990/yr)
--   Growth  ₱1,799/mo (₱17,990/yr)
--   Pro     ₱3,999/mo (₱39,990/yr)
-- Yearly stays 10× monthly (two months free).
--
-- Invoices already issued keep their amounts; the next invoice of each
-- subscription uses the new price.

update public.plans set monthly_price_centavos = 99900, annual_price_centavos = 999000
where id = 'starter';
update public.plans set monthly_price_centavos = 179900, annual_price_centavos = 1799000
where id = 'growth';
update public.plans set monthly_price_centavos = 399900, annual_price_centavos = 3999000
where id = 'pro';

-- Starter lists it after the court calendar; Growth inherits it ("Everything in Starter").
update public.plans
set features = array_remove(features, 'Day & night rates')
where id <> 'starter';
update public.plans
set features = case
  when array_position(features, 'Court calendar') is not null
    then features[1:array_position(features, 'Court calendar')]
         || 'Day & night rates'::text
         || features[array_position(features, 'Court calendar') + 1:]
  else features || 'Day & night rates'::text
end
where id = 'starter' and not ('Day & night rates' = any (features));

-- ===========================================================================
-- 20261101104100_trial_request_plan.sql
-- ===========================================================================

-- Purpose: a free-trial request remembers which plan the visitor wants
-- ("Start Free Trial" on Starter or Growth on the pricing page, or the plan
-- picked on the Contact form). Super Admin sees "Wants: Growth" and starts
-- the trial on that plan. NULL = not sure / didn't say.
--
-- submit_trial_request() gets a p_plan_id argument, so it's recreated. A
-- plan that isn't offered (hidden, "coming soon", unknown) is stored as
-- NULL rather than refusing the request.

alter table public.trial_requests
  add column plan_id text references public.plans (id) on delete set null;

comment on column public.trial_requests.plan_id is
  'Plan the visitor asked to try. NULL = not sure.';

drop function public.submit_trial_request(text, text, text, text, text, integer, text);

create function public.submit_trial_request(
  p_business_name text,
  p_contact_name text,
  p_email text,
  p_phone text default '',
  p_city text default '',
  p_courts integer default null,
  p_message text default '',
  p_plan_id text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_plan text;
  v_id uuid;
begin
  if btrim(coalesce(p_business_name, '')) = '' or btrim(coalesce(p_contact_name, '')) = '' then
    raise exception 'Enter your business name and your name.' using errcode = 'P0001';
  end if;
  if v_email !~ '^\S+@\S+\.\S+$' then
    raise exception 'Enter a valid email address.' using errcode = 'P0001';
  end if;
  if p_courts is not null and (p_courts < 1 or p_courts > 500) then
    raise exception 'Enter how many courts you have (1–500).' using errcode = 'P0001';
  end if;
  perform public.hit_rate_limit('trial:ip', public.client_ip(), 5, interval '1 hour');
  perform public.hit_rate_limit('trial:email', v_email, 3, interval '1 day');

  select id into v_plan from public.plans
  where id = p_plan_id and is_public and not coming_soon;

  insert into public.trial_requests (business_name, contact_name, email, phone, city, courts,
                                     message, plan_id)
  values (
    left(btrim(p_business_name), 100),
    left(btrim(p_contact_name), 100),
    left(v_email, 254),
    left(btrim(coalesce(p_phone, '')), 30),
    left(btrim(coalesce(p_city, '')), 60),
    p_courts,
    left(btrim(coalesce(p_message, '')), 1000),
    v_plan
  )
  returning id into v_id;
  return v_id;
end;
$$;

revoke execute on function
  public.submit_trial_request(text, text, text, text, text, integer, text, text)
  from public;
grant execute on function
  public.submit_trial_request(text, text, text, text, text, integer, text, text)
  to anon, authenticated;
